    { const char * tb_v357 = "// то, что видно из .ll (shared, tb_show_N, tb_new_X, обёртки): с --llvm без static\n"; *(const char * *)tb_grow(v_lines) = tb_v357; }
    { const char * tb_v358 = "#ifdef TB_LL\n"; *(const char * *)tb_grow(v_lines) = tb_v358; }
