    { const char * tb_v363 = "// Библиотека, которую Tachbit кладёт в начало каждой программы на C.\n"; *(const char * *)tb_grow(v_lines) = tb_v363; }
    { const char * tb_v364 = "// Это обычный C. Компилятор на Tachbit встраивает этот текст через runtime_text.tb,\n"; *(const char * *)tb_grow(v_lines) = tb_v364; }
    { const char * tb_v365 = "// который делает tools/embed_runtime.py. Поменял этот файл — запусти:\n"; *(const char * *)tb_grow(v_lines) = tb_v365; }
    { const char * tb_v366 = "//     python3 tools/embed_runtime.py\n"; *(const char * *)tb_grow(v_lines) = tb_v366; }
    { const char * tb_v367 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v367; }
    { const char * tb_v368 = "// ---------- режим без ОС (tb bare): своя маленькая библиотека вместо libc ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v368; }
    { const char * tb_v369 = "// Программа сама себе ОС: загружается через multiboot (QEMU, GRUB), пишет на экран\n"; *(const char * *)tb_grow(v_lines) = tb_v369; }
    { const char * tb_v370 = "// (текстовый режим VGA) и в последовательный порт COM1, память берёт из своего запаса.\n"; *(const char * *)tb_grow(v_lines) = tb_v370; }
    { const char * tb_v371 = "// Есть прерывания, таймер, клавиатура, задачи (background) и страницы памяти; файлов нет.\n"; *(const char * *)tb_grow(v_lines) = tb_v371; }
    { const char * tb_v372 = "#include <stddef.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v372; }
