    { const char * tb_v375 = "// «переменные потока» — настоящие: у каждой задачи свой блок, на него смотрит регистр FS\n"; *(const char * *)tb_grow(v_lines) = tb_v375; }
    { const char * tb_v376 = "// (так их не надо копировать при смене задачи, и на нескольких ядрах процессора у каждого свои)\n"; *(const char * *)tb_grow(v_lines) = tb_v376; }
    { const char * tb_v377 = "#define _Thread_local __thread __attribute__((tls_model(\"local-exec\")))\n"; *(const char * *)tb_grow(v_lines) = tb_v377; }
    { const char * tb_v378 = "#define EOF (-1)\n"; *(const char * *)tb_grow(v_lines) = tb_v378; }
    { const char * tb_v379 = "typedef struct tb_file FILE;\n"; *(const char * *)tb_grow(v_lines) = tb_v379; }
    { const char * tb_v380 = "#define stdout ((FILE *)1)\n"; *(const char * *)tb_grow(v_lines) = tb_v380; }
    { const char * tb_v381 = "#define stderr ((FILE *)2)\n"; *(const char * *)tb_grow(v_lines) = tb_v381; }
    { const char * tb_v382 = "typedef long pthread_t;   // 8 байт, как адрес: раскладка задачи та же, что в обычной программе\n"; *(const char * *)tb_grow(v_lines) = tb_v382; }
    { const char * tb_v383 = "typedef int pthread_mutex_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v383; }
    { const char * tb_v384 = "#define PTHREAD_MUTEX_INITIALIZER 0\n"; *(const char * *)tb_grow(v_lines) = tb_v384; }
    { const char * tb_v385 = "#define pthread_mutex_lock(m) ((void)(m))\n"; *(const char * *)tb_grow(v_lines) = tb_v385; }
    { const char * tb_v386 = "#define pthread_mutex_unlock(m) ((void)(m))\n"; *(const char * *)tb_grow(v_lines) = tb_v386; }
    { const char * tb_v387 = "#define _SC_NPROCESSORS_ONLN 0\n"; *(const char * *)tb_grow(v_lines) = tb_v387; }
    { const char * tb_v388 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v388; }
    { const char * tb_v389 = "TB_INL void tb_outb(unsigned short port, unsigned char v) { __asm__ volatile(\"outb %0, %1\" : : \"a\"(v), \"Nd\"(port)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v389; }
    { const char * tb_v390 = "TB_INL unsigned char tb_inb(unsigned short port) { unsigned char v; __asm__ volatile(\"inb %1, %0\" : \"=a\"(v) : \"Nd\"(port)); return v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v390; }
    { const char * tb_v391 = "TB_INL void tb_outw(unsigned short port, unsigned short v) { __asm__ volatile(\"outw %0, %1\" : : \"a\"(v), \"Nd\"(port)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v391; }
    { const char * tb_v392 = "TB_INL unsigned short tb_inw(unsigned short port) { unsigned short v; __asm__ volatile(\"inw %1, %0\" : \"=a\"(v) : \"Nd\"(port)); return v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v392; }
    { const char * tb_v393 = "TB_INL void tb_outl(unsigned short port, unsigned int v) { __asm__ volatile(\"outl %0, %1\" : : \"a\"(v), \"Nd\"(port)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v393; }
    { const char * tb_v394 = "TB_INL unsigned int tb_inl(unsigned short port) { unsigned int v; __asm__ volatile(\"inl %1, %0\" : \"=a\"(v) : \"Nd\"(port)); return v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v394; }
    { const char * tb_v395 = "// ядро процессора («звезда»): его номер, кого он сейчас ведёт, свой стек для пустого хода.\n"; *(const char * *)tb_grow(v_lines) = tb_v395; }
    { const char * tb_v396 = "// Регистр GS у каждого ядра смотрит на его запись (в самом начале — адрес её самой)\n"; *(const char * *)tb_grow(v_lines) = tb_v396; }
    { const char * tb_v397 = "#define TB_NCPU 16\n"; *(const char * *)tb_grow(v_lines) = tb_v397; }
    { const char * tb_v398 = "typedef struct tb_cpu_s {\n"; *(const char * *)tb_grow(v_lines) = tb_v398; }
    { const char * tb_v399 = "    struct tb_cpu_s *self;\n"; *(const char * *)tb_grow(v_lines) = tb_v399; }
    { const char * tb_v400 = "    int id, apic, run, slice, depth, prev;   // run: номер задачи (-1 — пустой ход); depth: вложенность «общего замка»; prev: задача, которую отпустить после смены стека\n"; *(const char * *)tb_grow(v_lines) = tb_v400; }
    { const char * tb_v401 = "    uint64_t *idle_frame;\n"; *(const char * *)tb_grow(v_lines) = tb_v401; }
    { const char * tb_v402 = "    unsigned char irq_tls[512 + 16] __attribute__((aligned(16)));   // переменные потока для функций прерывания\n"; *(const char * *)tb_grow(v_lines) = tb_v402; }
    { const char * tb_v403 = "    unsigned char idle_stack[16384] __attribute__((aligned(16)));\n"; *(const char * *)tb_grow(v_lines) = tb_v403; }
    { const char * tb_v404 = "    unsigned char df_stack[16384] __attribute__((aligned(16)));\n"; *(const char * *)tb_grow(v_lines) = tb_v404; }
    { const char * tb_v405 = "} tb_cpu;\n"; *(const char * *)tb_grow(v_lines) = tb_v405; }
