    { const char * tb_v407 = "TB_API int tb_ncpu = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v407; }
    { const char * tb_v408 = "TB_INL tb_cpu *tb_me(void) { tb_cpu *c; __asm__ volatile(\"movq %%gs:0, %0\" : \"=r\"(c)); return c; }\n"; *(const char * *)tb_grow(v_lines) = tb_v408; }
    { const char * tb_v409 = "// короткое дело библиотеки (память, экран, список задач): прерывания выключены и взят общий\n"; *(const char * *)tb_grow(v_lines) = tb_v409; }
    { const char * tb_v410 = "// замок — так его не делят ни прерывание, ни другое ядро процессора. Можно вкладывать\n"; *(const char * *)tb_grow(v_lines) = tb_v410; }
    { const char * tb_v411 = "TB_API volatile int tb_bkl = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v411; }
    { const char * tb_v412 = "TB_INL uint64_t tb_irq_save(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v412; }
    { const char * tb_v413 = "    uint64_t f;\n"; *(const char * *)tb_grow(v_lines) = tb_v413; }
    { const char * tb_v414 = "    __asm__ volatile(\"pushfq\\npopq %0\\ncli\" : \"=r\"(f) : : \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v414; }
    { const char * tb_v415 = "    tb_cpu *c = tb_me();\n"; *(const char * *)tb_grow(v_lines) = tb_v415; }
    { const char * tb_v416 = "    if (c->depth++ == 0)\n"; *(const char * *)tb_grow(v_lines) = tb_v416; }
    { const char * tb_v417 = "        while (__atomic_exchange_n(&tb_bkl, 1, __ATOMIC_ACQUIRE)) __builtin_ia32_pause();\n"; *(const char * *)tb_grow(v_lines) = tb_v417; }
    { const char * tb_v418 = "    return f;\n"; *(const char * *)tb_grow(v_lines) = tb_v418; }
    { const char * tb_v419 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v419; }
    { const char * tb_v420 = "TB_INL void tb_irq_restore(uint64_t f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v420; }
    { const char * tb_v421 = "    tb_cpu *c = tb_me();\n"; *(const char * *)tb_grow(v_lines) = tb_v421; }
    { const char * tb_v422 = "    if (--c->depth == 0) __atomic_store_n(&tb_bkl, 0, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v422; }
    { const char * tb_v423 = "    __asm__ volatile(\"pushq %0\\npopfq\" : : \"r\"(f) : \"memory\", \"cc\");\n"; *(const char * *)tb_grow(v_lines) = tb_v423; }
    { const char * tb_v424 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v424; }
    { const char * tb_v425 = "// отдать общий замок целиком (задача уходит навсегда — падает или кончилась)\n"; *(const char * *)tb_grow(v_lines) = tb_v425; }
    { const char * tb_v426 = "TB_INL void tb_bkl_drop(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v426; }
    { const char * tb_v427 = "    tb_cpu *c = tb_me();\n"; *(const char * *)tb_grow(v_lines) = tb_v427; }
    { const char * tb_v428 = "    if (c->depth > 0) { c->depth = 0; __atomic_store_n(&tb_bkl, 0, __ATOMIC_RELEASE); }\n"; *(const char * *)tb_grow(v_lines) = tb_v428; }
    { const char * tb_v429 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v429; }
    { const char * tb_v430 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v430; }
