    { const char * tb_v442 = "    if (tb_vrow == 25) {\n"; *(const char * *)tb_grow(v_lines) = tb_v442; }
    { const char * tb_v443 = "        for (int i = 0; i < 24 * 80; i++) tb_vga[i] = tb_vga[i + 80];\n"; *(const char * *)tb_grow(v_lines) = tb_v443; }
    { const char * tb_v444 = "        for (int i = 24 * 80; i < 25 * 80; i++) tb_vga[i] = (unsigned short)(tb_vcolor << 8 | ' ');\n"; *(const char * *)tb_grow(v_lines) = tb_v444; }
