    { const char * tb_v555 = "// выход: QEMU с -device isa-debug-exit закрывается, без него процессор просто спит\n"; *(const char * *)tb_grow(v_lines) = tb_v555; }
    { const char * tb_v556 = "__attribute__((noreturn)) static void exit(int code) {\n"; *(const char * *)tb_grow(v_lines) = tb_v556; }
