    { const char * tb_v562 = "// кладётся в корзину своего размера и выдаётся снова. Последний кусок отдаётся сразу.\n"; *(const char * *)tb_grow(v_lines) = tb_v562; }
    { const char * tb_v563 = "#define TB_HEAP (64 << 20)\n"; *(const char * *)tb_grow(v_lines) = tb_v563; }
    { const char * tb_v564 = "TB_API unsigned char tb_heap[TB_HEAP] __attribute__((aligned(16), section(\".tbheap\")));\n"; *(const char * *)tb_grow(v_lines) = tb_v564; }
