    { const char * tb_v567 = "TB_API int tb_cls(size_t n) { int k = 4; while (k < 31 && ((size_t)1 << k) < n) k++; return k; }\n"; *(const char * *)tb_grow(v_lines) = tb_v567; }
    { const char * tb_v568 = "TB_API void *tb_malloc0(size_t n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v568; }
    { const char * tb_v569 = "    int k = tb_cls(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v569; }
