    { const char * tb_v734 = "TB_API void qsort(void *base, size_t n, size_t size, int (*cmp)(const void *, const void *)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v734; }
    { const char * tb_v735 = "    unsigned char *a = base, tmp[64];\n"; *(const char * *)tb_grow(v_lines) = tb_v735; }
    { const char * tb_v736 = "    if (size > sizeof tmp) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v736; }
    { const char * tb_v737 = "    for (size_t i = 1; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v737; }
