    { const char * tb_v740 = "        while (j > 0 && cmp(a + (j - 1) * size, tmp) > 0) { memcpy(a + j * size, a + (j - 1) * size, size); j--; }\n"; *(const char * *)tb_grow(v_lines) = tb_v740; }
    { const char * tb_v741 = "        memcpy(a + j * size, tmp, size);\n"; *(const char * *)tb_grow(v_lines) = tb_v741; }
    { const char * tb_v742 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v742; }
    { const char * tb_v743 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v743; }
