    { const char * tb_v751 = "// on all cores здесь выполняется на одном ядре по очереди (как и было),\n"; *(const char * *)tb_grow(v_lines) = tb_v751; }
    { const char * tb_v752 = "// а background — настоящая задача: таймер переключает задачи каждые 10 мс.\n"; *(const char * *)tb_grow(v_lines) = tb_v752; }
