    { const char * tb_v754 = "TB_API int pthread_create(pthread_t *t, void *a, void *(*run)(void *), void *arg) { (void)t; (void)a; run(arg); return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v754; }
