    { const char * tb_v756 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v756; }
    { const char * tb_v757 = "// адреса из раскладки ядра (компоновщик): где код, где кончается нижняя память, где куча\n"; *(const char * *)tb_grow(v_lines) = tb_v757; }
    { const char * tb_v758 = "extern char tb_code_start[], tb_code_end[], tb_tls_start[], tb_tls_end[], tb_heap_area[], tb_kernel_end[];\n"; *(const char * *)tb_grow(v_lines) = tb_v758; }
