    { const char * tb_v761 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v761; }
    { const char * tb_v762 = "// авария ядра: красным на экран и в порт, потом стоп\n"; *(const char * *)tb_grow(v_lines) = tb_v762; }
    { const char * tb_v763 = "__attribute__((noreturn)) static void tb_panic(const char *what, uint64_t a, uint64_t b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v763; }
    { const char * tb_v764 = "    __asm__ volatile(\"cli\");\n"; *(const char * *)tb_grow(v_lines) = tb_v764; }
