    { const char * tb_v770 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v770; }
    { const char * tb_v771 = "// --- таблица сегментов x86-64: код 64 бита, данные, задача процессора (TSS, 16 байт) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v771; }
    { const char * tb_v772 = "// у каждого ядра процессора свой TSS (две записи по 8 байт): номер сегмента 0x18 + 16 × ядро\n"; *(const char * *)tb_grow(v_lines) = tb_v772; }
    { const char * tb_v773 = "TB_API uint64_t tb_gdt[3 + 2 * TB_NCPU] __attribute__((used)) = {0, 0x00AF9A000000FFFFULL, 0x00CF92000000FFFFULL};\n"; *(const char * *)tb_grow(v_lines) = tb_v773; }
    { const char * tb_v774 = "// TSS: ist[0] — отдельный стек для двойной ошибки (стек упёрся в сторожа — обработчику есть куда писать)\n"; *(const char * *)tb_grow(v_lines) = tb_v774; }
    { const char * tb_v775 = "typedef struct __attribute__((packed)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v775; }
    { const char * tb_v776 = "    uint32_t r0; uint64_t rsp[3]; uint64_t r1; uint64_t ist[7]; uint64_t r2; uint16_t r3, iomap;\n"; *(const char * *)tb_grow(v_lines) = tb_v776; }
    { const char * tb_v777 = "} tb_tss64;\n"; *(const char * *)tb_grow(v_lines) = tb_v777; }
    { const char * tb_v778 = "TB_API tb_tss64 tb_tsss[TB_NCPU] __attribute__((aligned(16)));\n"; *(const char * *)tb_grow(v_lines) = tb_v778; }
    { const char * tb_v779 = "TB_API uint64_t tb_idt[2 * 256] __attribute__((aligned(16)));\n"; *(const char * *)tb_grow(v_lines) = tb_v779; }
    { const char * tb_v780 = "TB_API struct __attribute__((packed)) { uint16_t lim; uint64_t base; } tb_gdtr, tb_idtr;\n"; *(const char * *)tb_grow(v_lines) = tb_v780; }
    { const char * tb_v781 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v781; }
    { const char * tb_v782 = "// 49 входов: 0..31 ошибки процессора, 32..47 железо (таймер, клавиатура ...), 48 — «уступить ход».\n"; *(const char * *)tb_grow(v_lines) = tb_v782; }
    { const char * tb_v783 = "// Кадр на стеке (снизу вверх): 512 байт дробей и SSE (fxsave), 15 регистров, номер, код ошибки,\n"; *(const char * *)tb_grow(v_lines) = tb_v783; }
    { const char * tb_v784 = "// и то, что положил процессор: rip, cs, rflags, rsp, ss. Задачи переключаются сменой кадра —\n"; *(const char * *)tb_grow(v_lines) = tb_v784; }
    { const char * tb_v785 = "// у каждой задачи свои регистры и свои дроби лежат в её кадре.\n"; *(const char * *)tb_grow(v_lines) = tb_v785; }
    { const char * tb_v786 = "extern char tb_isr_base[];\n"; *(const char * *)tb_grow(v_lines) = tb_v786; }
    { const char * tb_v787 = "__asm__(\".text\\n.balign 16\\n.global tb_isr_base\\ntb_isr_base:\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v787; }
    { const char * tb_v788 = "        \".set tb_v, 0\\n.rept 50\\n.balign 16\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v788; }
    { const char * tb_v789 = "        \".if (tb_v == 8) || (tb_v == 10) || (tb_v == 11) || (tb_v == 12) || (tb_v == 13) || (tb_v == 14) || (tb_v == 17) || (tb_v == 21)\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v789; }
    { const char * tb_v790 = "        \".else\\npushq $0\\n.endif\\npushq $tb_v\\njmp tb_isr_common\\n.set tb_v, tb_v + 1\\n.endr\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v790; }
    { const char * tb_v791 = "        \"tb_isr_common:\\ncld\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v791; }
    { const char * tb_v792 = "        \"pushq %rax\\npushq %rcx\\npushq %rdx\\npushq %rbx\\npushq %rbp\\npushq %rsi\\npushq %rdi\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v792; }
    { const char * tb_v793 = "        \"pushq %r8\\npushq %r9\\npushq %r10\\npushq %r11\\npushq %r12\\npushq %r13\\npushq %r14\\npushq %r15\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v793; }
    { const char * tb_v794 = "        \"subq $512, %rsp\\nfxsave (%rsp)\\nmovq %rsp, %rdi\\ncall tb_isr\\nmovq %rax, %rsp\\ncall tb_switch_done\\nfxrstor (%rsp)\\naddq $512, %rsp\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v794; }
    { const char * tb_v795 = "        \"popq %r15\\npopq %r14\\npopq %r13\\npopq %r12\\npopq %r11\\npopq %r10\\npopq %r9\\npopq %r8\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v795; }
    { const char * tb_v796 = "        \"popq %rdi\\npopq %rsi\\npopq %rbp\\npopq %rbx\\npopq %rdx\\npopq %rcx\\npopq %rax\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v796; }
    { const char * tb_v797 = "        \"addq $16, %rsp\\niretq\\n\");\n"; *(const char * *)tb_grow(v_lines) = tb_v797; }
    { const char * tb_v798 = "#define TB_F_VEC 79\n"; *(const char * *)tb_grow(v_lines) = tb_v798; }
    { const char * tb_v799 = "#define TB_F_ERR 80\n"; *(const char * *)tb_grow(v_lines) = tb_v799; }
    { const char * tb_v800 = "#define TB_F_RIP 81\n"; *(const char * *)tb_grow(v_lines) = tb_v800; }
    { const char * tb_v801 = "#define TB_FRAME (512 + 22 * 8)\n"; *(const char * *)tb_grow(v_lines) = tb_v801; }
    { const char * tb_v802 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v802; }
    { const char * tb_v803 = "// --- задачи: у каждой свой стек и свои «переменные потока» (temp, кэш длины) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v803; }
    { const char * tb_v804 = "#define TB_TLS_MAX 512\n"; *(const char * *)tb_grow(v_lines) = tb_v804; }
    { const char * tb_v805 = "#define TB_NTASK 32\n"; *(const char * *)tb_grow(v_lines) = tb_v805; }
    { const char * tb_v806 = "#define TB_TSTACK 65536\n"; *(const char * *)tb_grow(v_lines) = tb_v806; }
    { const char * tb_v807 = "typedef struct { pthread_t th; volatile int done; void *res; } tb_task;\n"; *(const char * *)tb_grow(v_lines) = tb_v807; }
    { const char * tb_v808 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v808; }
    { const char * tb_v809 = "    uint64_t *frame; int used; volatile int done;\n"; *(const char * *)tb_grow(v_lines) = tb_v809; }
    { const char * tb_v810 = "    void *(*run)(void *); void *arg; tb_task *t;\n"; *(const char * *)tb_grow(v_lines) = tb_v810; }
    { const char * tb_v811 = "    int on;                               // на каком ядре процессора идёт сейчас (-1 — ни на каком)\n"; *(const char * *)tb_grow(v_lines) = tb_v811; }
    { const char * tb_v812 = "    int no;                               // номер клетки: по порядку запуска (1, 2, 3 ...)\n"; *(const char * *)tb_grow(v_lines) = tb_v812; }
    { const char * tb_v813 = "    uint64_t gen; long long mem;          // поколение слота (для хозяина кусков) и байты клетки\n"; *(const char * *)tb_grow(v_lines) = tb_v813; }
    { const char * tb_v814 = "    int *locks[8]; int nlocks;            // замки, которые клетка держит сейчас\n"; *(const char * *)tb_grow(v_lines) = tb_v814; }
    { const char * tb_v815 = "    unsigned char tls[TB_TLS_MAX + 16] __attribute__((aligned(16)));   // блок переменных потока + адрес самого себя\n"; *(const char * *)tb_grow(v_lines) = tb_v815; }
    { const char * tb_v816 = "} tb_kslot;\n"; *(const char * *)tb_grow(v_lines) = tb_v816; }
    { const char * tb_v817 = "TB_API tb_kslot tb_slots[TB_NTASK];          // 0 — main\n"; *(const char * *)tb_grow(v_lines) = tb_v817; }
    { const char * tb_v818 = "TB_API unsigned char tb_tstacks[TB_NTASK][TB_TSTACK] __attribute__((aligned(4096)));\n"; *(const char * *)tb_grow(v_lines) = tb_v818; }
    { const char * tb_v819 = "TB_API int tb_nlive = 1, tb_cell_count = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v819; }
    { const char * tb_v820 = "// своё у каждой задачи (переменные потока): номер её слота; у функций прерывания tb_in_irq = 1\n"; *(const char * *)tb_grow(v_lines) = tb_v820; }
    { const char * tb_v821 = "TB_API _Thread_local int tb_cur = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v821; }
    { const char * tb_v822 = "TB_API _Thread_local int tb_in_irq = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v822; }
    { const char * tb_v823 = "TB_API unsigned char tb_fpu_init[512] __attribute__((aligned(16)));\n"; *(const char * *)tb_grow(v_lines) = tb_v823; }
    { const char * tb_v824 = "TB_API volatile uint64_t tb_ms = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v824; }
    { const char * tb_v825 = "TB_API void (*tb_irq_fn[16])(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v825; }
    { const char * tb_v826 = "TB_API uint16_t tb_pic_mask = 0xFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v826; }
    { const char * tb_v827 = "TB_API uint64_t tb_tls_size(void) { return (uint64_t)(tb_tls_end - tb_tls_start); }\n"; *(const char * *)tb_grow(v_lines) = tb_v827; }
    { const char * tb_v828 = "// блок переменных потока: начальные значения (образ от компоновщика), в конце — адрес конца\n"; *(const char * *)tb_grow(v_lines) = tb_v828; }
    { const char * tb_v829 = "// (так устроено у x86-64: FS указывает на конец блока, а там лежит он сам)\n"; *(const char * *)tb_grow(v_lines) = tb_v829; }
    { const char * tb_v830 = "TB_API unsigned char *tb_tls_fresh(unsigned char *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v830; }
    { const char * tb_v831 = "    uint64_t n = tb_tls_size();\n"; *(const char * *)tb_grow(v_lines) = tb_v831; }
    { const char * tb_v832 = "    memcpy(b, tb_tls_start, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v832; }
    { const char * tb_v833 = "    unsigned char *tp = b + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v833; }
    { const char * tb_v834 = "    *(uint64_t *)tp = (uint64_t)(uintptr_t)tp;\n"; *(const char * *)tb_grow(v_lines) = tb_v834; }
    { const char * tb_v835 = "    return tp;\n"; *(const char * *)tb_grow(v_lines) = tb_v835; }
    { const char * tb_v836 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v836; }
    { const char * tb_v837 = "TB_API void tb_set_fs(unsigned char *tp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v837; }
    { const char * tb_v838 = "    uint64_t v = (uint64_t)(uintptr_t)tp;\n"; *(const char * *)tb_grow(v_lines) = tb_v838; }
    { const char * tb_v839 = "    __asm__ volatile(\"wrmsr\" : : \"c\"(0xC0000100u), \"a\"((uint32_t)v), \"d\"((uint32_t)(v >> 32)) : \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v839; }
    { const char * tb_v840 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v840; }
    { const char * tb_v841 = "TB_API unsigned char *tb_tls_tp(unsigned char *b) { return b + tb_tls_size(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v841; }
    { const char * tb_v842 = "TB_INL void *tb_tls_self(void) { void *p; __asm__ volatile(\"movq %%fs:0, %0\" : \"=r\"(p)); return p; }\n"; *(const char * *)tb_grow(v_lines) = tb_v842; }
    { const char * tb_v843 = "// хозяин куска: номер слота и поколение; кусок клетки, которой уже нет, никому не засчитывается\n"; *(const char * *)tb_grow(v_lines) = tb_v843; }
    { const char * tb_v844 = "TB_API uint64_t tb_cell_charge(size_t bytes) {\n"; *(const char * *)tb_grow(v_lines) = tb_v844; }
    { const char * tb_v845 = "    if (tb_in_irq) return 0xFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v845; }
    { const char * tb_v846 = "    tb_kslot *s = &tb_slots[tb_cur];\n"; *(const char * *)tb_grow(v_lines) = tb_v846; }
    { const char * tb_v847 = "    if (tb_cur != 0 && s->mem + (long long)bytes > TB_CELL_QUOTA) return (uint64_t)-1;\n"; *(const char * *)tb_grow(v_lines) = tb_v847; }
    { const char * tb_v848 = "    s->mem += (long long)bytes;\n"; *(const char * *)tb_grow(v_lines) = tb_v848; }
    { const char * tb_v849 = "    return (uint64_t)tb_cur | (s->gen << 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v849; }
    { const char * tb_v850 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v850; }
    { const char * tb_v851 = "// хватит ли клетке квоты, если её кусок вырастет на месте (иначе растём через malloc — он и уронит)\n"; *(const char * *)tb_grow(v_lines) = tb_v851; }
    { const char * tb_v852 = "TB_API int tb_cell_fits(uint64_t tag, long long more) {\n"; *(const char * *)tb_grow(v_lines) = tb_v852; }
    { const char * tb_v853 = "    uint64_t i = tag & 0xFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v853; }
    { const char * tb_v854 = "    if (i == 0 || i >= TB_NTASK || tb_slots[i].gen != (tag >> 8)) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v854; }
    { const char * tb_v855 = "    return tb_slots[i].mem + more <= TB_CELL_QUOTA;\n"; *(const char * *)tb_grow(v_lines) = tb_v855; }
    { const char * tb_v856 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v856; }
    { const char * tb_v857 = "TB_API void tb_cell_refund(uint64_t tag, long long bytes) {\n"; *(const char * *)tb_grow(v_lines) = tb_v857; }
    { const char * tb_v858 = "    uint64_t i = tag & 0xFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v858; }
    { const char * tb_v859 = "    if (i >= TB_NTASK || tb_slots[i].gen != (tag >> 8) || !tb_slots[i].used) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v859; }
    { const char * tb_v860 = "    tb_slots[i].mem -= bytes;\n"; *(const char * *)tb_grow(v_lines) = tb_v860; }
    { const char * tb_v861 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v861; }
    { const char * tb_v862 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v862; }
    { const char * tb_v863 = "TB_API void tb_pic_apply(void) { tb_outb(0x21, (unsigned char)tb_pic_mask); tb_outb(0xA1, (unsigned char)(tb_pic_mask >> 8)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v863; }
