    { const char * tb_v1203 = "        if (memcmp((void *)(uintptr_t)a, \"RSD PTR \", 8) == 0) rsdp = (unsigned char *)(uintptr_t)a;\n"; *(const char * *)tb_grow(v_lines) = tb_v1203; }
    { const char * tb_v1204 = "    if (!rsdp) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1204; }
    { const char * tb_v1205 = "    unsigned char *rsdt = (unsigned char *)(uintptr_t)*(uint32_t *)(rsdp + 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v1205; }
