    { const char * tb_v1234 = "        \"  movl $0xC0000080, %ecx\\n  rdmsr\\n  orl $0x100, %eax\\n  wrmsr\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1234; }
    { const char * tb_v1235 = "        \"  movl %cr0, %eax\\n  andl $0xFFFFFFFB, %eax\\n  orl $0x80010002, %eax\\n  movl %eax, %cr0\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1235; }
    { const char * tb_v1236 = "        \"  ljmpl $0x18, $(0x8000 + (tb_tr64 - tb_tramp))\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1236; }
