    { const char * tb_v1656 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1656; }
    { const char * tb_v1657 = "typedef struct { void *(*run)(void *); void *arg; } tb_tramp;\n"; *(const char * *)tb_grow(v_lines) = tb_v1657; }
