    { const char * tb_v1956 = "    return (char *)a;\n"; *(const char * *)tb_grow(v_lines) = tb_v1956; }
    { const char * tb_v1957 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1957; }
    { const char * tb_v1958 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1958; }
    { const char * tb_v1959 = "// страницы по 64 КБ берём у системы пачкой по 4 МБ; пустые страницы возвращаются в запас\n"; *(const char * *)tb_grow(v_lines) = tb_v1959; }
    { const char * tb_v1960 = "TB_API char *tb_gfresh = 0, *tb_gfresh_end = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1960; }
    { const char * tb_v1961 = "TB_API void *tb_gspare = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1961; }
    { const char * tb_v1962 = "TB_API char *tb_gpage_mem(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1962; }
    { const char * tb_v1963 = "    if (tb_gspare) { void *p = tb_gspare; tb_gspare = *(void **)p; *(void **)p = 0; return p; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1963; }
    { const char * tb_v1964 = "    if (tb_gfresh == tb_gfresh_end) { tb_gfresh = tb_gsys(64 * TB_GPG); tb_gfresh_end = tb_gfresh + 64 * TB_GPG; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1964; }
    { const char * tb_v1965 = "    char *p = tb_gfresh;\n"; *(const char * *)tb_grow(v_lines) = tb_v1965; }
