    { const char * tb_v1969 = "TB_API tb_gpage *tb_gnewpage(int cls, int np) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1969; }
    { const char * tb_v1970 = "    tb_gpage *pg = calloc(1, sizeof(tb_gpage));\n"; *(const char * *)tb_grow(v_lines) = tb_v1970; }
