    { const char * tb_v1977 = "    pg->free = 0; pg->bump = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1977; }
    { const char * tb_v1978 = "    pg->nfree = pg->nblocks;\n"; *(const char * *)tb_grow(v_lines) = tb_v1978; }
