    { const char * tb_v1980 = "    tb_gmap_add(pg, TB_GPG);\n"; *(const char * *)tb_grow(v_lines) = tb_v1980; }
    { const char * tb_v1981 = "    pg->anext = tb_gavail[np][cls]; tb_gavail[np][cls] = pg; pg->in_avail = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1981; }
    { const char * tb_v1982 = "    return pg;\n"; *(const char * *)tb_grow(v_lines) = tb_v1982; }
    { const char * tb_v1983 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1983; }
    { const char * tb_v1984 = "#define TB_GIDX(pg, off) ((long long)(((unsigned long long)(off) * (pg)->inv) >> 32))\n"; *(const char * *)tb_grow(v_lines) = tb_v1984; }
    { const char * tb_v1985 = "// блок, внутрь которого указывает адрес a (или 0, если это не наша занятая память)\n"; *(const char * *)tb_grow(v_lines) = tb_v1985; }
    { const char * tb_v1986 = "TB_INL char *tb_gblock(uintptr_t a, tb_gpage **out) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1986; }
    { const char * tb_v1987 = "    if (a < tb_glo || a >= tb_ghi) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1987; }
    { const char * tb_v1988 = "    tb_gpage *pg = tb_gmap_get(a);\n"; *(const char * *)tb_grow(v_lines) = tb_v1988; }
