    { const char * tb_v1999 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1999; }
    { const char * tb_v2000 = "TB_API void tb_gc_collect(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v2000; }
