    { const char * tb_v2368 = "        l->data = tb_resize(l->data, old, l->cap * l->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2368; }
    { const char * tb_v2369 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2369; }
