    { const char * tb_v2386 = "TB_API tb_list *tb_bits_from(long long n, const unsigned char *src) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2386; }
    { const char * tb_v2387 = "    tb_list *l = tb_mem(sizeof(tb_list));\n"; *(const char * *)tb_grow(v_lines) = tb_v2387; }
    { const char * tb_v2388 = "    long long words = (n + 63) / 64 + (n == 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2388; }
    { const char * tb_v2389 = "    l->len = n; l->cap = words * 64; l->size = 0; l->data = tb_mem_np(words * 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v2389; }
    { const char * tb_v2390 = "    memset(l->data, 0, words * 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v2390; }
