    { const char * tb_v2393 = "    return l;\n"; *(const char * *)tb_grow(v_lines) = tb_v2393; }
    { const char * tb_v2394 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2394; }
    { const char * tb_v2395 = "// бит без проверки номера (для each — номер всегда внутри)\n"; *(const char * *)tb_grow(v_lines) = tb_v2395; }
    { const char * tb_v2396 = "#define TB_BIT(l, i) ((_Bool)((((unsigned long long *)(l)->data)[(i) >> 6] >> ((i) & 63)) & 1))\n"; *(const char * *)tb_grow(v_lines) = tb_v2396; }
    { const char * tb_v2397 = "TB_INL _Bool tb_bget(tb_list *l, long long i, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2397; }
    { const char * tb_v2398 = "    if (TB_RARE((unsigned long long)i >= (unsigned long long)l->len)) tb_crash(line, \"номер за пределами списка\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2398; }
    { const char * tb_v2399 = "    return TB_BIT(l, i);\n"; *(const char * *)tb_grow(v_lines) = tb_v2399; }
    { const char * tb_v2400 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2400; }
    { const char * tb_v2401 = "TB_INL void tb_bset(tb_list *l, long long i, _Bool v, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2401; }
    { const char * tb_v2402 = "    if (TB_RARE((unsigned long long)i >= (unsigned long long)l->len)) tb_crash(line, \"номер за пределами списка\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2402; }
    { const char * tb_v2403 = "    unsigned long long *w = (unsigned long long *)l->data + (i >> 6), m = 1ULL << (i & 63);\n"; *(const char * *)tb_grow(v_lines) = tb_v2403; }
    { const char * tb_v2404 = "    *w = v ? (*w | m) : (*w & ~m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2404; }
    { const char * tb_v2405 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2405; }
    { const char * tb_v2406 = "TB_INL void tb_badd(tb_list *l, _Bool v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2406; }
    { const char * tb_v2407 = "    if (TB_RARE(l->len >= l->cap)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2407; }
    { const char * tb_v2408 = "        if (l->cap < 0) tb_crash(0, \"список нельзя растить, пока по нему идёт each ... by N (и сам кусок растить нельзя)\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2408; }
    { const char * tb_v2409 = "        long long old = l->cap / 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v2409; }
    { const char * tb_v2410 = "        l->cap = l->cap * 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v2410; }
    { const char * tb_v2411 = "        l->data = tb_resize(l->data, old, l->cap / 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v2411; }
    { const char * tb_v2412 = "        memset(l->data + old, 0, l->cap / 8 - old);\n"; *(const char * *)tb_grow(v_lines) = tb_v2412; }
    { const char * tb_v2413 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2413; }
    { const char * tb_v2414 = "    long long i = l->len++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2414; }
    { const char * tb_v2415 = "    unsigned long long *w = (unsigned long long *)l->data + (i >> 6), m = 1ULL << (i & 63);\n"; *(const char * *)tb_grow(v_lines) = tb_v2415; }
    { const char * tb_v2416 = "    *w = v ? (*w | m) : (*w & ~m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2416; }
