    { const char * tb_v2817 = "// ---------- http_get: страница из интернета через curl (есть на Mac и почти на любом Linux) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2817; }
    { const char * tb_v2818 = "TB_API const char *tb_http_get(const char *url) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2818; }
    { const char * tb_v2819 = "    if (strncmp(url, \"http://\", 7) != 0 && strncmp(url, \"https://\", 8) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2819; }
    { const char * tb_v2820 = "        tb_err = tb_cat(\"адрес должен начинаться с http:// или https://: \", url);\n"; *(const char * *)tb_grow(v_lines) = tb_v2820; }
    { const char * tb_v2821 = "        return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v2821; }
    { const char * tb_v2822 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2822; }
    { const char * tb_v2823 = "    // адрес — в одинарных кавычках для shell: ' внутри адреса пишется как '\\''\n"; *(const char * *)tb_grow(v_lines) = tb_v2823; }
    { const char * tb_v2824 = "    size_t n = strlen(url);\n"; *(const char * *)tb_grow(v_lines) = tb_v2824; }
    { const char * tb_v2825 = "    char *cmd = malloc(n * 4 + 80);\n"; *(const char * *)tb_grow(v_lines) = tb_v2825; }
    { const char * tb_v2826 = "    if (!cmd) { tb_err = \"не хватило памяти\"; return \"\"; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2826; }
    { const char * tb_v2827 = "#ifdef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v2827; }
    { const char * tb_v2828 = "    // curl.exe есть в Windows 10 и новее; адрес — в двойных кавычках для cmd.exe,\n"; *(const char * *)tb_grow(v_lines) = tb_v2828; }
    { const char * tb_v2829 = "    // (внутри кавычек & | < > ^ для cmd — простые знаки), а \" внутри адреса — как %22\n"; *(const char * *)tb_grow(v_lines) = tb_v2829; }
    { const char * tb_v2830 = "    size_t k = (size_t)sprintf(cmd, \"curl.exe -fsSL --max-time 30 \\\"\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2830; }
    { const char * tb_v2831 = "    for (size_t i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2831; }
    { const char * tb_v2832 = "        unsigned char ch = (unsigned char)url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v2832; }
    { const char * tb_v2833 = "        if (ch == '\"' || ch < 32) { sprintf(cmd + k, \"%%%02X\", ch); k += 3; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2833; }
    { const char * tb_v2834 = "        else cmd[k++] = url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v2834; }
    { const char * tb_v2835 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2835; }
    { const char * tb_v2836 = "    strcpy(cmd + k, \"\\\" 2>NUL\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2836; }
    { const char * tb_v2837 = "    FILE *p = popen(cmd, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2837; }
    { const char * tb_v2838 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v2838; }
    { const char * tb_v2839 = "    size_t k = (size_t)sprintf(cmd, \"curl -fsSL --max-time 30 '\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2839; }
    { const char * tb_v2840 = "    for (size_t i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2840; }
    { const char * tb_v2841 = "        if (url[i] == '\\'') { memcpy(cmd + k, \"'\\\\''\", 4); k += 4; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2841; }
    { const char * tb_v2842 = "        else cmd[k++] = url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v2842; }
    { const char * tb_v2843 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2843; }
    { const char * tb_v2844 = "    strcpy(cmd + k, \"' 2>/dev/null\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2844; }
    { const char * tb_v2845 = "    FILE *p = popen(cmd, \"r\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2845; }
