    { const char * tb_v2861 = "TB_API const char *tb_js_ws(const char *p) { while (*p == ' ' || *p == '\\n' || *p == '\\r' || *p == '\\t') p++; return p; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2861; }
    { const char * tb_v2862 = "// пропустить одно значение; адрес после него или 0, если JSON сломан\n"; *(const char * *)tb_grow(v_lines) = tb_v2862; }
    { const char * tb_v2863 = "TB_API const char *tb_js_skip(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2863; }
    { const char * tb_v2864 = "    p = tb_js_ws(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v2864; }
    { const char * tb_v2865 = "    if (*p == '\"') {\n"; *(const char * *)tb_grow(v_lines) = tb_v2865; }
    { const char * tb_v2866 = "        p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2866; }
    { const char * tb_v2867 = "        while (*p && *p != '\"') { if (*p == '\\\\' && p[1]) p++; p++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2867; }
    { const char * tb_v2868 = "        return *p ? p + 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2868; }
    { const char * tb_v2869 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2869; }
    { const char * tb_v2870 = "    if (*p == '{' || *p == '[') {\n"; *(const char * *)tb_grow(v_lines) = tb_v2870; }
    { const char * tb_v2871 = "        int d = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2871; }
    { const char * tb_v2872 = "        while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2872; }
    { const char * tb_v2873 = "            if (*p == '\"') { p = tb_js_skip(p); if (!p) return 0; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2873; }
    { const char * tb_v2874 = "            if (*p == '{' || *p == '[') d++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2874; }
    { const char * tb_v2875 = "            else if (*p == '}' || *p == ']') { d--; if (d == 0) return p + 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2875; }
    { const char * tb_v2876 = "            p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2876; }
    { const char * tb_v2877 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v2877; }
    { const char * tb_v2878 = "        return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2878; }
    { const char * tb_v2879 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2879; }
    { const char * tb_v2880 = "    const char *s = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2880; }
