    { const char * tb_v3049 = "TB_API tb_list *tb_copy(tb_list *l) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3049; }
    { const char * tb_v3050 = "    if (l->size == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3050; }
    { const char * tb_v3051 = "        tb_list *r = tb_mem(sizeof(tb_list));\n"; *(const char * *)tb_grow(v_lines) = tb_v3051; }
