    { const char * tb_v3058 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3058; }
    { const char * tb_v3059 = "TB_API void tb_sort_list(tb_list *l, int (*cmp)(const void *, const void *)) { qsort(l->data, l->len, l->size, cmp); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3059; }
    { const char * tb_v3060 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3060; }
    { const char * tb_v3061 = "// ---------- dict: ключи и значения лежат в двух списках по порядку добавления,\n"; *(const char * *)tb_grow(v_lines) = tb_v3061; }
    { const char * tb_v3062 = "// а найти номер по ключу можно тремя способами (mode):\n"; *(const char * *)tb_grow(v_lines) = tb_v3062; }
    { const char * tb_v3063 = "//   1 — «номер = адрес»: ключи int шли подряд base, base+1, base+2 ... — номер = ключ - base, без поиска;\n"; *(const char * *)tb_grow(v_lines) = tb_v3063; }
    { const char * tb_v3064 = "//   2 — «адресное хранение»: ключи int лежат плотно — pos[ключ - base] = номер + 1, один взгляд;\n"; *(const char * *)tb_grow(v_lines) = tb_v3064; }
    { const char * tb_v3065 = "//   0 — таблица slots с хешем (текст или разбросанные числа) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3065; }
    { const char * tb_v3066 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v3066; }
    { const char * tb_v3067 = "    tb_list *keys; tb_list *vals; long long *slots; long long nslots; int text;\n"; *(const char * *)tb_grow(v_lines) = tb_v3067; }
    { const char * tb_v3068 = "    int mode; long long base; long long *pos; long long npos;\n"; *(const char * *)tb_grow(v_lines) = tb_v3068; }
    { const char * tb_v3069 = "} tb_dict;\n"; *(const char * *)tb_grow(v_lines) = tb_v3069; }
    { const char * tb_v3070 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3070; }
    { const char * tb_v3071 = "// ячейка таблицы: номер ключа + 1 (младшие 40 бит) и метка из старших битов хеша\n"; *(const char * *)tb_grow(v_lines) = tb_v3071; }
    { const char * tb_v3072 = "#define TB_DAT ((1LL << 40) - 1)\n"; *(const char * *)tb_grow(v_lines) = tb_v3072; }
    { const char * tb_v3073 = "#define TB_DTAG(h) ((long long)(((h) >> 40) << 40) & ~TB_DAT & 0x7FFFFFFFFFFFFFFFLL)\n"; *(const char * *)tb_grow(v_lines) = tb_v3073; }
    { const char * tb_v3074 = "TB_API unsigned long long tb_hash(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3074; }
    { const char * tb_v3075 = "    unsigned long long h = 1469598103934665603ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v3075; }
    { const char * tb_v3076 = "    if (d->text) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3076; }
    { const char * tb_v3077 = "        for (const unsigned char *p = *(const unsigned char * const *)k; *p; p++) { h ^= *p; h *= 1099511628211ULL; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3077; }
    { const char * tb_v3078 = "    } else {\n"; *(const char * *)tb_grow(v_lines) = tb_v3078; }
    { const char * tb_v3079 = "        h ^= (unsigned long long)*(const long long *)k;\n"; *(const char * *)tb_grow(v_lines) = tb_v3079; }
    { const char * tb_v3080 = "        h *= 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v3080; }
    { const char * tb_v3081 = "        h ^= h >> 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v3081; }
    { const char * tb_v3082 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3082; }
    { const char * tb_v3083 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v3083; }
    { const char * tb_v3084 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3084; }
    { const char * tb_v3085 = "TB_API int tb_keq(tb_dict *d, const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3085; }
    { const char * tb_v3086 = "    if (d->text) return strcmp(*(const char * const *)a, *(const char * const *)b) == 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3086; }
    { const char * tb_v3087 = "    return *(const long long *)a == *(const long long *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v3087; }
    { const char * tb_v3088 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3088; }
    { const char * tb_v3089 = "TB_INL long long tb_dfind(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3089; }
    { const char * tb_v3090 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3090; }
    { const char * tb_v3091 = "        unsigned long long at = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v3091; }
    { const char * tb_v3092 = "        return at < (unsigned long long)d->keys->len ? (long long)at : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3092; }
    { const char * tb_v3093 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3093; }
    { const char * tb_v3094 = "    if (d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3094; }
    { const char * tb_v3095 = "        unsigned long long o = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v3095; }
    { const char * tb_v3096 = "        return o < (unsigned long long)d->npos ? d->pos[o] - 1 : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3096; }
    { const char * tb_v3097 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3097; }
    { const char * tb_v3098 = "    unsigned long long h = tb_hash(d, k), mask = d->nslots - 1, i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v3098; }
    { const char * tb_v3099 = "    long long tag = TB_DTAG(h);\n"; *(const char * *)tb_grow(v_lines) = tb_v3099; }
    { const char * tb_v3100 = "    while (d->slots[i] != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3100; }
    { const char * tb_v3101 = "        long long sl = d->slots[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v3101; }
    { const char * tb_v3102 = "        // метка хеша совпала — только тогда сравниваем сами ключи (текст — дорого)\n"; *(const char * *)tb_grow(v_lines) = tb_v3102; }
    { const char * tb_v3103 = "        if ((sl & ~TB_DAT) == tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3103; }
    { const char * tb_v3104 = "            long long at = (sl & TB_DAT) - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3104; }
    { const char * tb_v3105 = "            if (tb_keq(d, d->keys->data + at * d->keys->size, k)) return at;\n"; *(const char * *)tb_grow(v_lines) = tb_v3105; }
    { const char * tb_v3106 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3106; }
    { const char * tb_v3107 = "        i = (i + 1) & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v3107; }
    { const char * tb_v3108 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3108; }
    { const char * tb_v3109 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3109; }
    { const char * tb_v3110 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3110; }
    { const char * tb_v3111 = "// память для таблиц dict — там же, где лежат его ключи (временная или обычная)\n"; *(const char * *)tb_grow(v_lines) = tb_v3111; }
    { const char * tb_v3112 = "TB_API void *tb_dalloc(tb_dict *d, void *old, long long bytes) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3112; }
    { const char * tb_v3113 = "    if (old && !(tb_nchunks > 0 && tb_in_temp(old))) tb_gc_free(old);\n"; *(const char * *)tb_grow(v_lines) = tb_v3113; }
    { const char * tb_v3114 = "    void *p = tb_in_cur_temp(d->keys->data) ? tb_temp_alloc(bytes) : tb_gc_alloc_np(bytes);\n"; *(const char * *)tb_grow(v_lines) = tb_v3114; }
    { const char * tb_v3115 = "    if (!p) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3115; }
    { const char * tb_v3116 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3116; }
    { const char * tb_v3117 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3117; }
    { const char * tb_v3118 = "TB_API void tb_dreindex(tb_dict *d, long long nslots) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3118; }
    { const char * tb_v3119 = "    d->mode = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3119; }
    { const char * tb_v3120 = "    if (d->pos) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3120; }
    { const char * tb_v3121 = "        if (!(tb_nchunks > 0 && tb_in_temp(d->pos))) tb_gc_free(d->pos);\n"; *(const char * *)tb_grow(v_lines) = tb_v3121; }
    { const char * tb_v3122 = "        d->pos = 0; d->npos = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3122; }
    { const char * tb_v3123 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3123; }
    { const char * tb_v3124 = "    d->nslots = nslots;\n"; *(const char * *)tb_grow(v_lines) = tb_v3124; }
    { const char * tb_v3125 = "    d->slots = tb_dalloc(d, d->slots, nslots * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v3125; }
    { const char * tb_v3126 = "    memset(d->slots, 0, nslots * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v3126; }
    { const char * tb_v3127 = "    unsigned long long mask = nslots - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3127; }
    { const char * tb_v3128 = "    for (long long at = 0; at < d->keys->len; at++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3128; }
    { const char * tb_v3129 = "        unsigned long long h = tb_hash(d, d->keys->data + at * d->keys->size), i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v3129; }
    { const char * tb_v3130 = "        while (d->slots[i] != 0) i = (i + 1) & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v3130; }
    { const char * tb_v3131 = "        d->slots[i] = (at + 1) | TB_DTAG(h);\n"; *(const char * *)tb_grow(v_lines) = tb_v3131; }
    { const char * tb_v3132 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3132; }
    { const char * tb_v3133 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3133; }
    { const char * tb_v3134 = "// перейти на таблицу с хешем (ключ ушёл далеко от остальных или его удалили)\n"; *(const char * *)tb_grow(v_lines) = tb_v3134; }
    { const char * tb_v3135 = "TB_API void tb_dto_hash(tb_dict *d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3135; }
    { const char * tb_v3136 = "    long long n = 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v3136; }
    { const char * tb_v3137 = "    while (n < d->keys->len * 2 + 2) n *= 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v3137; }
    { const char * tb_v3138 = "    tb_dreindex(d, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3138; }
    { const char * tb_v3139 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3139; }
    { const char * tb_v3140 = "// mode 2: таблица pos на ключи base .. base+npos-1\n"; *(const char * *)tb_grow(v_lines) = tb_v3140; }
    { const char * tb_v3141 = "TB_API void tb_dto_pos(tb_dict *d, long long npos) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3141; }
    { const char * tb_v3142 = "    long long *p = tb_dalloc(d, 0, npos * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v3142; }
    { const char * tb_v3143 = "    memset(p, 0, npos * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v3143; }
    { const char * tb_v3144 = "    const long long *ks = (const long long *)d->keys->data;\n"; *(const char * *)tb_grow(v_lines) = tb_v3144; }
    { const char * tb_v3145 = "    for (long long at = 0; at < d->keys->len; at++) p[ks[at] - d->base] = at + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3145; }
    { const char * tb_v3146 = "    if (d->pos && !(tb_nchunks > 0 && tb_in_temp(d->pos))) tb_gc_free(d->pos);\n"; *(const char * *)tb_grow(v_lines) = tb_v3146; }
    { const char * tb_v3147 = "    d->pos = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3147; }
    { const char * tb_v3148 = "    d->npos = npos;\n"; *(const char * *)tb_grow(v_lines) = tb_v3148; }
    { const char * tb_v3149 = "    d->mode = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v3149; }
    { const char * tb_v3150 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3150; }
    { const char * tb_v3151 = "TB_API tb_dict *tb_dict_new(int text, long long vsize) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3151; }
    { const char * tb_v3152 = "    tb_dict *d = tb_mem(sizeof(tb_dict));\n"; *(const char * *)tb_grow(v_lines) = tb_v3152; }
    { const char * tb_v3153 = "    d->text = text;\n"; *(const char * *)tb_grow(v_lines) = tb_v3153; }
    { const char * tb_v3154 = "    d->keys = text ? tb_list_new(sizeof(const char *)) : tb_list_new_np(sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v3154; }
    { const char * tb_v3155 = "    d->vals = tb_list_new(vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v3155; }
    { const char * tb_v3156 = "    d->slots = 0; d->pos = 0; d->npos = 0; d->base = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3156; }
    { const char * tb_v3157 = "    if (text) tb_dreindex(d, 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v3157; }
    { const char * tb_v3158 = "    else { d->mode = 1; d->nslots = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3158; }
    { const char * tb_v3159 = "    return d;\n"; *(const char * *)tb_grow(v_lines) = tb_v3159; }
    { const char * tb_v3160 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3160; }
    { const char * tb_v3161 = "// .clear(): список снова пустой; свой кусок памяти отдаётся (если он не временный).\n"; *(const char * *)tb_grow(v_lines) = tb_v3161; }
    { const char * tb_v3162 = "// Тексты и obj внутри не удаляются: на них могут смотреть другие переменные.\n"; *(const char * *)tb_grow(v_lines) = tb_v3162; }
    { const char * tb_v3163 = "TB_API void tb_lclear(tb_list *l, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3163; }
    { const char * tb_v3164 = "    if (l->cap < 0) tb_crash(line, \".clear() нельзя, пока по списку идёт each ... by N\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3164; }
    { const char * tb_v3165 = "    int temp = tb_nchunks > 0 && tb_in_temp(l->data);\n"; *(const char * *)tb_grow(v_lines) = tb_v3165; }
    { const char * tb_v3166 = "    if (!temp) tb_gc_free(l->data);\n"; *(const char * *)tb_grow(v_lines) = tb_v3166; }
    { const char * tb_v3167 = "    long long cap = l->size == 0 ? 64 : 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v3167; }
    { const char * tb_v3168 = "    long long bytes = l->size == 0 ? 8 : l->size * 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v3168; }
    { const char * tb_v3169 = "    l->data = tb_in_cur_temp(l->data) ? tb_temp_alloc(bytes) : tb_gc_alloc(bytes);\n"; *(const char * *)tb_grow(v_lines) = tb_v3169; }
    { const char * tb_v3170 = "    if (l->data == 0) tb_crash(line, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3170; }
    { const char * tb_v3171 = "    memset(l->data, 0, bytes);\n"; *(const char * *)tb_grow(v_lines) = tb_v3171; }
    { const char * tb_v3172 = "    l->len = 0; l->cap = cap;\n"; *(const char * *)tb_grow(v_lines) = tb_v3172; }
    { const char * tb_v3173 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3173; }
    { const char * tb_v3174 = "// --llvm: число ключей (из .ll не надо знать устройство tb_dict)\n"; *(const char * *)tb_grow(v_lines) = tb_v3174; }
    { const char * tb_v3175 = "TB_INL long long tb_dlen(tb_dict *d) { return d->keys->len; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3175; }
    { const char * tb_v3176 = "TB_INL tb_list *tb_dkeys_copy(tb_dict *d) { return tb_copy(d->keys); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3176; }
    { const char * tb_v3177 = "TB_INL tb_list *tb_dvals_copy(tb_dict *d) { return tb_copy(d->vals); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3177; }
    { const char * tb_v3178 = "TB_API void tb_dclear(tb_dict *d, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3178; }
    { const char * tb_v3179 = "    tb_lclear(d->keys, line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3179; }
    { const char * tb_v3180 = "    tb_lclear(d->vals, line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3180; }
    { const char * tb_v3181 = "    if (d->pos && !(tb_nchunks > 0 && tb_in_temp(d->pos))) tb_gc_free(d->pos);\n"; *(const char * *)tb_grow(v_lines) = tb_v3181; }
    { const char * tb_v3182 = "    if (d->slots && !(tb_nchunks > 0 && tb_in_temp(d->slots))) tb_gc_free(d->slots);\n"; *(const char * *)tb_grow(v_lines) = tb_v3182; }
