    { const char * tb_v3187 = "// новый ключ int k: можно ли остаться без поиска (mode 1 или 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v3187; }
    { const char * tb_v3188 = "TB_API void tb_dplace_int(tb_dict *d, long long k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3188; }
    { const char * tb_v3189 = "    long long n = d->keys->len;          // уже вместе с новым ключом\n"; *(const char * *)tb_grow(v_lines) = tb_v3189; }
    { const char * tb_v3190 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3190; }
    { const char * tb_v3191 = "        if (n == 1) { d->base = k; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3191; }
