    { const char * tb_v3199 = "            long long want = d->npos * 2 > o + 1 ? d->npos * 2 : o + 1 + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v3199; }
    { const char * tb_v3200 = "            if (want < 16) want = 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v3200; }
