    { const char * tb_v3207 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3207; }
    { const char * tb_v3208 = "// место под значение ключа k; если ключа нет — добавить со значением *def\n"; *(const char * *)tb_grow(v_lines) = tb_v3208; }
    { const char * tb_v3209 = "TB_API void *tb_dput(tb_dict *d, const void *k, const void *def) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3209; }
    { const char * tb_v3210 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v3210; }
    { const char * tb_v3211 = "    if (at >= 0) return d->vals->data + at * d->vals->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v3211; }
    { const char * tb_v3212 = "    memcpy(tb_grow(d->keys), k, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3212; }
    { const char * tb_v3213 = "    void *v = tb_grow(d->vals);\n"; *(const char * *)tb_grow(v_lines) = tb_v3213; }
    { const char * tb_v3214 = "    if (def) memcpy(v, def, d->vals->size); else memset(v, 0, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3214; }
    { const char * tb_v3215 = "    if (d->mode != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3215; }
    { const char * tb_v3216 = "        // без поиска; если ключ лёг далеко, tb_dplace_int сам перейдёт на хеш и впишет все ключи\n"; *(const char * *)tb_grow(v_lines) = tb_v3216; }
    { const char * tb_v3217 = "        tb_dplace_int(d, *(const long long *)k);\n"; *(const char * *)tb_grow(v_lines) = tb_v3217; }
    { const char * tb_v3218 = "        return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v3218; }
    { const char * tb_v3219 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3219; }
    { const char * tb_v3220 = "    if (d->keys->len * 2 > d->nslots) tb_dreindex(d, d->nslots * 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v3220; }
    { const char * tb_v3221 = "    else {\n"; *(const char * *)tb_grow(v_lines) = tb_v3221; }
    { const char * tb_v3222 = "        unsigned long long h = tb_hash(d, k), mask = d->nslots - 1, i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v3222; }
    { const char * tb_v3223 = "        while (d->slots[i] != 0) i = (i + 1) & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v3223; }
    { const char * tb_v3224 = "        d->slots[i] = d->keys->len | TB_DTAG(h);\n"; *(const char * *)tb_grow(v_lines) = tb_v3224; }
