    { const char * tb_v3226 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v3226; }
    { const char * tb_v3227 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3227; }
    { const char * tb_v3228 = "TB_API void *tb_dget(tb_dict *d, const void *k, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3228; }
