    { const char * tb_v3230 = "    if (TB_RARE(at < 0)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3230; }
    { const char * tb_v3231 = "        if (d->text) tb_crash(line, tb_cat(\"в dict нет ключа: \", *(const char * const *)k));\n"; *(const char * *)tb_grow(v_lines) = tb_v3231; }
    { const char * tb_v3232 = "        tb_crash(line, tb_cat(\"в dict нет ключа: \", tb_itos(*(const long long *)k)));\n"; *(const char * *)tb_grow(v_lines) = tb_v3232; }
    { const char * tb_v3233 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3233; }
