    { const char * tb_v3264 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3264; }
    { const char * tb_v3265 = "// ---------- холодные качества obj: своя память, отдельно от горячих ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3265; }
    { const char * tb_v3266 = "TB_API void *tb_cold_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3266; }
    { const char * tb_v3267 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3267; }
