    { const char * tb_v3276 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v3276; }
    { const char * tb_v3277 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3277; }
    { const char * tb_v3278 = "// ---------- obj: память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3278; }
    { const char * tb_v3279 = "// Внутри temp и шага цикла — из временной памяти, иначе — из памяти с уборкой.\n"; *(const char * *)tb_grow(v_lines) = tb_v3279; }
    { const char * tb_v3280 = "TB_API void *tb_obj_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3280; }
    { const char * tb_v3281 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3281; }
    { const char * tb_v3282 = "    return tb_gc_alloc(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3282; }
