    { const char * tb_v3285 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3285; }
    { const char * tb_v3286 = "    return tb_gc_alloc_np(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3286; }
    { const char * tb_v3287 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3287; }
    { const char * tb_v3288 = "// ---------- background: работа в своём потоке ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3288; }
    { const char * tb_v3289 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3289; }
    { const char * tb_v3290 = "typedef struct { pthread_t th; int done; void *res; } tb_task;\n"; *(const char * *)tb_grow(v_lines) = tb_v3290; }
    { const char * tb_v3291 = "TB_API void tb_task_start(tb_task *t, void *(*run)(void *), void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3291; }
    { const char * tb_v3292 = "    t->done = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3292; }
