    { const char * tb_v3294 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3294; }
    { const char * tb_v3295 = "// a.wait: дождаться потока (один раз) и отдать адрес ответа\n"; *(const char * *)tb_grow(v_lines) = tb_v3295; }
    { const char * tb_v3296 = "TB_API void *tb_wait(tb_task *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3296; }
    { const char * tb_v3297 = "    if (!t->done) { pthread_join(t->th, 0); t->done = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3297; }
    { const char * tb_v3298 = "    return t->res;\n"; *(const char * *)tb_grow(v_lines) = tb_v3298; }
    { const char * tb_v3299 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3299; }
    { const char * tb_v3300 = "// a.crashed: в обычной программе падение задачи роняет всю программу — сюда доходят только целые\n"; *(const char * *)tb_grow(v_lines) = tb_v3300; }
    { const char * tb_v3301 = "TB_API _Bool tb_crashed(tb_task *t) { tb_wait(t); return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3301; }
    { const char * tb_v3302 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3302; }
    { const char * tb_v3303 = "TB_API int tb_dhas(tb_dict *d, const void *k) { return tb_dfind(d, k) >= 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3303; }
    { const char * tb_v3304 = "TB_API void tb_dremove(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3304; }
    { const char * tb_v3305 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v3305; }
    { const char * tb_v3306 = "    if (at < 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3306; }
    { const char * tb_v3307 = "    if (d->mode != 0) tb_dto_hash(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v3307; }
    { const char * tb_v3308 = "    long long last = d->keys->len - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3308; }
    { const char * tb_v3309 = "    // на место удалённого ставим последний: порядок меняется только у него\n"; *(const char * *)tb_grow(v_lines) = tb_v3309; }
    { const char * tb_v3310 = "    memcpy(d->keys->data + at * d->keys->size, d->keys->data + last * d->keys->size, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3310; }
    { const char * tb_v3311 = "    memcpy(d->vals->data + at * d->vals->size, d->vals->data + last * d->vals->size, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3311; }
