    { const char * tb_v3334 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3334; }
    { const char * tb_v3335 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3335; }
    { const char * tb_v3336 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3336; }
    { const char * tb_v3337 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v3337; }
