    { const char * tb_v3614 = "    if (tb_memchk()) { tb_mem_touch((uintptr_t)src, (uint64_t)n, line); tb_mem_touch((uintptr_t)dst, (uint64_t)n, line); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3614; }
    { const char * tb_v3615 = "    memmove((void *)(uintptr_t)dst, (const void *)(uintptr_t)src, (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3615; }
    { const char * tb_v3616 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3616; }
    { const char * tb_v3617 = "// ---------- use c: функции из C ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3617; }
    { const char * tb_v3618 = "// настоящее имя функции C (на Mac у имён в библиотеке спереди _)\n"; *(const char * *)tb_grow(v_lines) = tb_v3618; }
    { const char * tb_v3619 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v3619; }
    { const char * tb_v3620 = "#define TB_CSYM(s) __asm__(\"_\" s)\n"; *(const char * *)tb_grow(v_lines) = tb_v3620; }
    { const char * tb_v3621 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3621; }
    { const char * tb_v3622 = "#define TB_CSYM(s) __asm__(s)\n"; *(const char * *)tb_grow(v_lines) = tb_v3622; }
    { const char * tb_v3623 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3623; }
    { const char * tb_v3624 = "// текст из C: копия в память Tachbit (C может потом поменять или отдать свой); NULL → \"\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3624; }
    { const char * tb_v3625 = "TB_API const char *tb_ctext(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3625; }
    { const char * tb_v3626 = "    if (!p) return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v3626; }
    { const char * tb_v3627 = "    size_t n = strlen(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v3627; }
    { const char * tb_v3628 = "    char *s = tb_tmem(n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3628; }
    { const char * tb_v3629 = "    memcpy(s, p, n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3629; }
    { const char * tb_v3630 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v3630; }
    { const char * tb_v3631 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3631; }
    { const char * tb_v3632 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3632; }
    { const char * tb_v3633 = "// ---------- zone: область памяти. Много кусков берутся быстро и освобождаются разом ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3633; }
    { const char * tb_v3634 = "// Зона — цепочка больших кусков. zone_take отрезает от текущего куска (16 байт выравнивание, нули),\n"; *(const char * *)tb_grow(v_lines) = tb_v3634; }
    { const char * tb_v3635 = "// кончился кусок — берёт новый. zone_clear отдаёт всё, кроме первого куска; zone_free — всё.\n"; *(const char * *)tb_grow(v_lines) = tb_v3635; }
    { const char * tb_v3636 = "#define TB_ZONE_LIVE 0x5A4F4E454C495645ULL\n"; *(const char * *)tb_grow(v_lines) = tb_v3636; }
    { const char * tb_v3637 = "typedef struct tb_zchunk { struct tb_zchunk *next; uint64_t size, used, pad; } tb_zchunk;   // 32 байта: данные с выравниванием 16\n"; *(const char * *)tb_grow(v_lines) = tb_v3637; }
    { const char * tb_v3638 = "typedef struct { uint64_t magic, step; tb_zchunk *first, *cur; } tb_zone;\n"; *(const char * *)tb_grow(v_lines) = tb_v3638; }
    { const char * tb_v3639 = "// данные куска: сразу за заголовком, с выравниванием 16 (malloc в ядре выравнивает меньше)\n"; *(const char * *)tb_grow(v_lines) = tb_v3639; }
    { const char * tb_v3640 = "#define TB_ZDATA(k) ((unsigned char *)(((uintptr_t)((k) + 1) + 15) & ~(uintptr_t)15))\n"; *(const char * *)tb_grow(v_lines) = tb_v3640; }
    { const char * tb_v3641 = "static tb_zchunk *tb_zone_chunk(uint64_t n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3641; }
    { const char * tb_v3642 = "    tb_zchunk *k = malloc(sizeof(tb_zchunk) + (size_t)n + 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v3642; }
    { const char * tb_v3643 = "    if (!k) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3643; }
    { const char * tb_v3644 = "    k->next = 0; k->size = n; k->used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3644; }
    { const char * tb_v3645 = "    memset(TB_ZDATA(k), 0, (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3645; }
    { const char * tb_v3646 = "    return k;\n"; *(const char * *)tb_grow(v_lines) = tb_v3646; }
    { const char * tb_v3647 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3647; }
    { const char * tb_v3648 = "// zone_new(байт): первый кусок такого размера; дальше куски того же размера (или больше, если нужно)\n"; *(const char * *)tb_grow(v_lines) = tb_v3648; }
    { const char * tb_v3649 = "TB_API long long tb_zone_new(long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3649; }
    { const char * tb_v3650 = "    (void)line;\n"; *(const char * *)tb_grow(v_lines) = tb_v3650; }
    { const char * tb_v3651 = "    if (n <= 0) { tb_err = \"zone_new: размер должен быть больше нуля\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3651; }
    { const char * tb_v3652 = "    if ((unsigned long long)n > ((unsigned long long)1 << 46)) { tb_err = \"zone_new: слишком большой размер\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3652; }
    { const char * tb_v3653 = "    tb_zone *z = malloc(sizeof(tb_zone));\n"; *(const char * *)tb_grow(v_lines) = tb_v3653; }
    { const char * tb_v3654 = "    if (!z) { tb_err = \"zone_new: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3654; }
    { const char * tb_v3655 = "    uint64_t step = ((uint64_t)n + 15) & ~(uint64_t)15;\n"; *(const char * *)tb_grow(v_lines) = tb_v3655; }
    { const char * tb_v3656 = "    z->first = z->cur = tb_zone_chunk(step);\n"; *(const char * *)tb_grow(v_lines) = tb_v3656; }
    { const char * tb_v3657 = "    if (!z->first) { free(z); tb_err = \"zone_new: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3657; }
    { const char * tb_v3658 = "    z->magic = TB_ZONE_LIVE; z->step = step;\n"; *(const char * *)tb_grow(v_lines) = tb_v3658; }
    { const char * tb_v3659 = "    return (long long)(uintptr_t)z;\n"; *(const char * *)tb_grow(v_lines) = tb_v3659; }
    { const char * tb_v3660 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3660; }
    { const char * tb_v3661 = "static tb_zone *tb_zone_own(long long a, int line, const char *who) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3661; }
    { const char * tb_v3662 = "    tb_zone *z = (tb_zone *)(uintptr_t)a;\n"; *(const char * *)tb_grow(v_lines) = tb_v3662; }
    { const char * tb_v3663 = "    if (!z || z->magic != TB_ZONE_LIVE) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3663; }
    { const char * tb_v3664 = "        char buf[120];\n"; *(const char * *)tb_grow(v_lines) = tb_v3664; }
    { const char * tb_v3665 = "        snprintf(buf, sizeof buf, \"%s: это не зона из zone_new или она уже освобождена\", who);\n"; *(const char * *)tb_grow(v_lines) = tb_v3665; }
    { const char * tb_v3666 = "        tb_crash(line, buf);\n"; *(const char * *)tb_grow(v_lines) = tb_v3666; }
    { const char * tb_v3667 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3667; }
    { const char * tb_v3668 = "    return z;\n"; *(const char * *)tb_grow(v_lines) = tb_v3668; }
    { const char * tb_v3669 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3669; }
    { const char * tb_v3670 = "// zone_take(зона, байт): адрес нового куска (нули)\n"; *(const char * *)tb_grow(v_lines) = tb_v3670; }
    { const char * tb_v3671 = "TB_API long long tb_zone_take(long long a, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3671; }
    { const char * tb_v3672 = "    tb_zone *z = tb_zone_own(a, line, \"zone_take\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3672; }
    { const char * tb_v3673 = "    if (n <= 0) tb_crash(line, \"zone_take: размер должен быть больше нуля\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3673; }
    { const char * tb_v3674 = "    uint64_t need = ((uint64_t)n + 15) & ~(uint64_t)15;\n"; *(const char * *)tb_grow(v_lines) = tb_v3674; }
    { const char * tb_v3675 = "    tb_zchunk *k = z->cur;\n"; *(const char * *)tb_grow(v_lines) = tb_v3675; }
    { const char * tb_v3676 = "    if (k->size - k->used < need) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3676; }
    { const char * tb_v3677 = "        if (k->next && k->next->size >= need) k = k->next;\n"; *(const char * *)tb_grow(v_lines) = tb_v3677; }
    { const char * tb_v3678 = "        else {\n"; *(const char * *)tb_grow(v_lines) = tb_v3678; }
    { const char * tb_v3679 = "            tb_zchunk *nk = tb_zone_chunk(need > z->step ? need : z->step);\n"; *(const char * *)tb_grow(v_lines) = tb_v3679; }
    { const char * tb_v3680 = "            if (!nk) tb_crash(line, \"zone_take: не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3680; }
    { const char * tb_v3681 = "            nk->next = k->next; k->next = nk; k = nk;\n"; *(const char * *)tb_grow(v_lines) = tb_v3681; }
    { const char * tb_v3682 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3682; }
    { const char * tb_v3683 = "        z->cur = k;\n"; *(const char * *)tb_grow(v_lines) = tb_v3683; }
    { const char * tb_v3684 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3684; }
    { const char * tb_v3685 = "    unsigned char *p = TB_ZDATA(k) + k->used;\n"; *(const char * *)tb_grow(v_lines) = tb_v3685; }
    { const char * tb_v3686 = "    k->used += need;\n"; *(const char * *)tb_grow(v_lines) = tb_v3686; }
    { const char * tb_v3687 = "    return (long long)(uintptr_t)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3687; }
    { const char * tb_v3688 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3688; }
    { const char * tb_v3689 = "// zone_clear(зона): всё взятое больше не нужно; первый кусок остаётся для новых zone_take\n"; *(const char * *)tb_grow(v_lines) = tb_v3689; }
    { const char * tb_v3690 = "TB_API void tb_zone_clear(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3690; }
    { const char * tb_v3691 = "    tb_zone *z = tb_zone_own(a, line, \"zone_clear\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3691; }
    { const char * tb_v3692 = "    tb_zchunk *k = z->first->next;\n"; *(const char * *)tb_grow(v_lines) = tb_v3692; }
    { const char * tb_v3693 = "    while (k) { tb_zchunk *nx = k->next; free(k); k = nx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3693; }
    { const char * tb_v3694 = "    z->first->next = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3694; }
    { const char * tb_v3695 = "    memset(TB_ZDATA(z->first), 0, (size_t)z->first->used);\n"; *(const char * *)tb_grow(v_lines) = tb_v3695; }
    { const char * tb_v3696 = "    z->first->used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3696; }
    { const char * tb_v3697 = "    z->cur = z->first;\n"; *(const char * *)tb_grow(v_lines) = tb_v3697; }
    { const char * tb_v3698 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3698; }
    { const char * tb_v3699 = "// zone_free(зона): отдать всё; zone_free(0) ничего не делает\n"; *(const char * *)tb_grow(v_lines) = tb_v3699; }
    { const char * tb_v3700 = "TB_API void tb_zone_free(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3700; }
    { const char * tb_v3701 = "    if (a == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3701; }
    { const char * tb_v3702 = "    tb_zone *z = tb_zone_own(a, line, \"zone_free\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3702; }
    { const char * tb_v3703 = "    tb_zchunk *k = z->first;\n"; *(const char * *)tb_grow(v_lines) = tb_v3703; }
    { const char * tb_v3704 = "    while (k) { tb_zchunk *nx = k->next; free(k); k = nx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3704; }
    { const char * tb_v3705 = "    z->magic = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3705; }
    { const char * tb_v3706 = "    free(z);\n"; *(const char * *)tb_grow(v_lines) = tb_v3706; }
    { const char * tb_v3707 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3707; }
    { const char * tb_v3708 = "// zone_used(зона): сколько байт взято (с выравниванием)\n"; *(const char * *)tb_grow(v_lines) = tb_v3708; }
    { const char * tb_v3709 = "TB_API long long tb_zone_used(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3709; }
    { const char * tb_v3710 = "    tb_zone *z = tb_zone_own(a, line, \"zone_used\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3710; }
    { const char * tb_v3711 = "    long long s = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3711; }
    { const char * tb_v3712 = "    for (tb_zchunk *k = z->first; k; k = k->next) s += (long long)k->used;\n"; *(const char * *)tb_grow(v_lines) = tb_v3712; }
    { const char * tb_v3713 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v3713; }
    { const char * tb_v3714 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3714; }
    { const char * tb_v3715 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3715; }
    { const char * tb_v3716 = "// ---------- syscall(номер, ...): прямой вызов ядра ОС (Linux, Mac). Ответ -1 → -номер ошибки ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3716; }
    { const char * tb_v3717 = "#if !defined(TB_BARE) && !defined(_WIN32)\n"; *(const char * *)tb_grow(v_lines) = tb_v3717; }
    { const char * tb_v3718 = "#include <sys/syscall.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v3718; }
    { const char * tb_v3719 = "#include <errno.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v3719; }
    { const char * tb_v3720 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v3720; }
    { const char * tb_v3721 = "#pragma clang diagnostic push\n"; *(const char * *)tb_grow(v_lines) = tb_v3721; }
    { const char * tb_v3722 = "#pragma clang diagnostic ignored \"-Wdeprecated-declarations\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3722; }
    { const char * tb_v3723 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3723; }
    { const char * tb_v3724 = "TB_API long long tb_syscall(long long n, long long a, long long b, long long c, long long d, long long e, long long f, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3724; }
    { const char * tb_v3725 = "    (void)line;\n"; *(const char * *)tb_grow(v_lines) = tb_v3725; }
    { const char * tb_v3726 = "    long r = syscall((long)n, (long)a, (long)b, (long)c, (long)d, (long)e, (long)f);\n"; *(const char * *)tb_grow(v_lines) = tb_v3726; }
    { const char * tb_v3727 = "    if (r == -1) return -(long long)errno;\n"; *(const char * *)tb_grow(v_lines) = tb_v3727; }
    { const char * tb_v3728 = "    return (long long)r;\n"; *(const char * *)tb_grow(v_lines) = tb_v3728; }
    { const char * tb_v3729 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3729; }
    { const char * tb_v3730 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v3730; }
    { const char * tb_v3731 = "#pragma clang diagnostic pop\n"; *(const char * *)tb_grow(v_lines) = tb_v3731; }
    { const char * tb_v3732 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3732; }
    { const char * tb_v3733 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3733; }
    { const char * tb_v3734 = "TB_API long long tb_syscall(long long n, long long a, long long b, long long c, long long d, long long e, long long f, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3734; }
    { const char * tb_v3735 = "    (void)n; (void)a; (void)b; (void)c; (void)d; (void)e; (void)f;\n"; *(const char * *)tb_grow(v_lines) = tb_v3735; }
    { const char * tb_v3736 = "    tb_crash(line, \"syscall есть только на Linux и Mac\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3736; }
    { const char * tb_v3737 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3737; }
    { const char * tb_v3738 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3738; }
    { const char * tb_v3739 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3739; }
    { const char * tb_v3740 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3740; }
    { const char * tb_v3741 = "// ---------- shape: поля с размером прямо в памяти (регистры, заголовки пакетов) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3741; }
    { const char * tb_v3742 = "// k = смещение × 2^20 + байт (1, 2, 4, 8; 0 — bytes: отдать адрес) + 16 со знаком + 32 big\n"; *(const char * *)tb_grow(v_lines) = tb_v3742; }
    { const char * tb_v3743 = "//     + 64 × первый бит + 4096 × сколько бит (0 — поле целиком).\n"; *(const char * *)tb_grow(v_lines) = tb_v3743; }
    { const char * tb_v3744 = "// Поле читается и пишется одним volatile-доступом своей ширины: регистр u32 — одной 32-битной операцией.\n"; *(const char * *)tb_grow(v_lines) = tb_v3744; }
    { const char * tb_v3745 = "static inline uint64_t tb_shape_raw(uintptr_t p, int nb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3745; }
    { const char * tb_v3746 = "    if (nb == 1) return *(volatile uint8_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3746; }
    { const char * tb_v3747 = "    if (nb == 2) return *(volatile uint16_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3747; }
    { const char * tb_v3748 = "    if (nb == 4) return *(volatile uint32_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3748; }
    { const char * tb_v3749 = "    return *(volatile uint64_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3749; }
    { const char * tb_v3750 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3750; }
    { const char * tb_v3751 = "static inline void tb_shape_put(uintptr_t p, int nb, uint64_t v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3751; }
    { const char * tb_v3752 = "    if (nb == 1) *(volatile uint8_t *)p = (uint8_t)v;\n"; *(const char * *)tb_grow(v_lines) = tb_v3752; }
    { const char * tb_v3753 = "    else if (nb == 2) *(volatile uint16_t *)p = (uint16_t)v;\n"; *(const char * *)tb_grow(v_lines) = tb_v3753; }
