    { const char * tb_v4330 = "            int v = r[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v4330; }
    { const char * tb_v4331 = "            if (f == 1) v += a; else if (f == 2) v += b; else if (f == 3) v += (a + b) / 2; else if (f == 4) v += tb_paeth(a, b, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v4331; }
    { const char * tb_v4332 = "            r[i] = (unsigned char)v;\n"; *(const char * *)tb_grow(v_lines) = tb_v4332; }
    { const char * tb_v4333 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v4333; }
    { const char * tb_v4334 = "        prev = r;\n"; *(const char * *)tb_grow(v_lines) = tb_v4334; }
    { const char * tb_v4335 = "        for (unsigned x = 0; x < w; x++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4335; }
    { const char * tb_v4336 = "            unsigned s[4] = { 0, 0, 0, 255 }, raw[4] = { 0, 0, 0, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v4336; }
    { const char * tb_v4337 = "            for (int k = 0; k < ch; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4337; }
    { const char * tb_v4338 = "                if (depth == 8) raw[k] = r[x * ch + k], s[k] = raw[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v4338; }
    { const char * tb_v4339 = "                else if (depth == 16) raw[k] = ((unsigned)r[(x * ch + k) * 2] << 8) | r[(x * ch + k) * 2 + 1], s[k] = raw[k] >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v4339; }
    { const char * tb_v4340 = "                else {\n"; *(const char * *)tb_grow(v_lines) = tb_v4340; }
    { const char * tb_v4341 = "                    unsigned bit = x * depth, v = (r[bit / 8] >> (8 - depth - bit % 8)) & ((1u << depth) - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4341; }
    { const char * tb_v4342 = "                    raw[k] = v; s[k] = ctype == 3 ? v : v * 255 / ((1u << depth) - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4342; }
    { const char * tb_v4343 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v4343; }
    { const char * tb_v4344 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v4344; }
    { const char * tb_v4345 = "            unsigned R, G, B, A;\n"; *(const char * *)tb_grow(v_lines) = tb_v4345; }
    { const char * tb_v4346 = "            if (ctype == 3) { unsigned i = s[0] < 256 ? s[0] : 0; R = pal[i][0]; G = pal[i][1]; B = pal[i][2]; A = pal[i][3]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4346; }
    { const char * tb_v4347 = "            else if (ctype == 0 || ctype == 4) { R = G = B = s[0]; A = ctype == 4 ? s[1] : (trns && raw[0] == key[0] ? 0 : 255); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4347; }
    { const char * tb_v4348 = "            else { R = s[0]; G = s[1]; B = s[2]; A = ctype == 6 ? s[3] : (trns && raw[0] == key[0] && raw[1] == key[1] && raw[2] == key[2] ? 0 : 255); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4348; }
    { const char * tb_v4349 = "            px[(size_t)y * w + x] = (A << 24) | (R << 16) | (G << 8) | B;\n"; *(const char * *)tb_grow(v_lines) = tb_v4349; }
    { const char * tb_v4350 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v4350; }
    { const char * tb_v4351 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4351; }
    { const char * tb_v4352 = "    free(z.out);\n"; *(const char * *)tb_grow(v_lines) = tb_v4352; }
    { const char * tb_v4353 = "    *pw = (int)w; *ph = (int)h;\n"; *(const char * *)tb_grow(v_lines) = tb_v4353; }
    { const char * tb_v4354 = "    return px;\n"; *(const char * *)tb_grow(v_lines) = tb_v4354; }
    { const char * tb_v4355 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4355; }
    { const char * tb_v4356 = "// все картинки программы: точки подряд в одном большом массиве (его же видит видеокарта)\n"; *(const char * *)tb_grow(v_lines) = tb_v4356; }
    { const char * tb_v4357 = "typedef struct { int w, h; uint32_t off; } tb_image;\n"; *(const char * *)tb_grow(v_lines) = tb_v4357; }
    { const char * tb_v4358 = "TB_API tb_image *tb_imgs = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4358; }
    { const char * tb_v4359 = "TB_API int tb_nimg = 0, tb_img_dirty = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4359; }
    { const char * tb_v4360 = "TB_API uint32_t *tb_imgpx = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4360; }
    { const char * tb_v4361 = "TB_API size_t tb_imgpx_n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4361; }
    { const char * tb_v4362 = "TB_API long long tb_load_image(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4362; }
    { const char * tb_v4363 = "    FILE *f = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4363; }
    { const char * tb_v4364 = "    if (!f) { tb_err = \"нет такого файла картинки\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4364; }
    { const char * tb_v4365 = "    fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v4365; }
    { const char * tb_v4366 = "    unsigned char *d = sz > 0 ? malloc((size_t)sz) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4366; }
    { const char * tb_v4367 = "    if (!d || fread(d, 1, (size_t)sz, f) != (size_t)sz) { fclose(f); free(d); tb_err = \"не могу прочитать файл картинки\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4367; }
    { const char * tb_v4368 = "    fclose(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v4368; }
    { const char * tb_v4369 = "    int w = 0, h = 0; const char *why = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4369; }
    { const char * tb_v4370 = "    uint32_t *px = tb_png(d, (size_t)sz, &w, &h, &why);\n"; *(const char * *)tb_grow(v_lines) = tb_v4370; }
    { const char * tb_v4371 = "    free(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v4371; }
    { const char * tb_v4372 = "    if (!px) { tb_err = why; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4372; }
    { const char * tb_v4373 = "    size_t need = tb_imgpx_n + (size_t)w * h;\n"; *(const char * *)tb_grow(v_lines) = tb_v4373; }
    { const char * tb_v4374 = "    if (need > 0xFFFFFFFFu) { free(px); tb_err = \"слишком много картинок\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4374; }
    { const char * tb_v4375 = "    uint32_t *all = realloc(tb_imgpx, need * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v4375; }
    { const char * tb_v4376 = "    tb_image *list = realloc(tb_imgs, (size_t)(tb_nimg + 1) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v4376; }
    { const char * tb_v4377 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v4377; }
    { const char * tb_v4378 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v4378; }
    { const char * tb_v4379 = "    if (!all || !list) { free(px); tb_err = \"не хватило памяти\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4379; }
    { const char * tb_v4380 = "    memcpy(tb_imgpx + tb_imgpx_n, px, (size_t)w * h * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v4380; }
    { const char * tb_v4381 = "    free(px);\n"; *(const char * *)tb_grow(v_lines) = tb_v4381; }
    { const char * tb_v4382 = "    tb_imgs[tb_nimg].w = w; tb_imgs[tb_nimg].h = h; tb_imgs[tb_nimg].off = (uint32_t)tb_imgpx_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4382; }
    { const char * tb_v4383 = "    tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v4383; }
    { const char * tb_v4384 = "    tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4384; }
    { const char * tb_v4385 = "    return tb_nimg++;\n"; *(const char * *)tb_grow(v_lines) = tb_v4385; }
    { const char * tb_v4386 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4386; }
    { const char * tb_v4387 = "TB_API long long tb_image_w(long long i) { return i >= 0 && i < tb_nimg ? tb_imgs[i].w : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4387; }
    { const char * tb_v4388 = "TB_API long long tb_image_h(long long i) { return i >= 0 && i < tb_nimg ? tb_imgs[i].h : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4388; }
    { const char * tb_v4389 = "// ---------- шрифты TTF: свой чтец (таблицы glyf, без чужих библиотек) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4389; }
    { const char * tb_v4390 = "// Буква рисуется на процессоре один раз в маленькую картинку с прозрачностью (сглаживание),\n"; *(const char * *)tb_grow(v_lines) = tb_v4390; }
    { const char * tb_v4391 = "// дальше её рисуют и видеокарта, и процессор одинаково: точка = (цвет * a + фон * (255 - a)) / 255.\n"; *(const char * *)tb_grow(v_lines) = tb_v4391; }
    { const char * tb_v4392 = "typedef struct { unsigned char *d; size_t n; uint32_t glyf, loca, hmtx, cmap; int upem, locfmt, nglyphs, nhm, asc, desc, cfmt; } tb_font_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v4392; }
    { const char * tb_v4393 = "TB_API tb_font_t *tb_fonts = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4393; }
    { const char * tb_v4394 = "TB_API int tb_nfonts = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4394; }
    { const char * tb_v4395 = "static unsigned tb_u16(const tb_font_t *f, size_t o) { return o + 2 <= f->n ? (unsigned)(f->d[o] << 8 | f->d[o + 1]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4395; }
    { const char * tb_v4396 = "static int tb_s16(const tb_font_t *f, size_t o) { return (int16_t)tb_u16(f, o); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4396; }
    { const char * tb_v4397 = "static uint32_t tb_u32(const tb_font_t *f, size_t o) { return o + 4 <= f->n ? ((uint32_t)f->d[o] << 24 | (uint32_t)f->d[o + 1] << 16 | (uint32_t)f->d[o + 2] << 8 | f->d[o + 3]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4397; }
    { const char * tb_v4398 = "static uint32_t tb_ttf_table(const tb_font_t *f, size_t base, const char *tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4398; }
    { const char * tb_v4399 = "    unsigned n = tb_u16(f, base + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v4399; }
    { const char * tb_v4400 = "    for (unsigned i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4400; }
    { const char * tb_v4401 = "        size_t e = base + 12 + 16 * (size_t)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v4401; }
    { const char * tb_v4402 = "        if (e + 16 <= f->n && memcmp(f->d + e, tag, 4) == 0) return tb_u32(f, e + 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v4402; }
    { const char * tb_v4403 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4403; }
    { const char * tb_v4404 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4404; }
    { const char * tb_v4405 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4405; }
    { const char * tb_v4406 = "TB_API void tb_gpu_blend_probe(void);   // TB_GPU_CHECK: проба смешивания букв (ниже)\n"; *(const char * *)tb_grow(v_lines) = tb_v4406; }
    { const char * tb_v4407 = "TB_API long long tb_load_font(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4407; }
    { const char * tb_v4408 = "    FILE *fp = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4408; }
    { const char * tb_v4409 = "    if (!fp) { tb_err = tb_cat(\"нет такого файла шрифта: \", path); return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4409; }
    { const char * tb_v4410 = "    fseek(fp, 0, SEEK_END); long sz = ftell(fp); fseek(fp, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v4410; }
    { const char * tb_v4411 = "    unsigned char *d = sz > 12 ? malloc((size_t)sz) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4411; }
    { const char * tb_v4412 = "    if (!d || fread(d, 1, (size_t)sz, fp) != (size_t)sz) { fclose(fp); free(d); tb_err = \"не могу прочитать файл шрифта\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4412; }
    { const char * tb_v4413 = "    fclose(fp);\n"; *(const char * *)tb_grow(v_lines) = tb_v4413; }
    { const char * tb_v4414 = "    tb_font_t f = { d, (size_t)sz };\n"; *(const char * *)tb_grow(v_lines) = tb_v4414; }
    { const char * tb_v4415 = "    size_t base = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4415; }
    { const char * tb_v4416 = "    if (memcmp(d, \"ttcf\", 4) == 0) base = tb_u32(&f, 12);   // сборник шрифтов (.ttc): берём первый\n"; *(const char * *)tb_grow(v_lines) = tb_v4416; }
    { const char * tb_v4417 = "    uint32_t head = tb_ttf_table(&f, base, \"head\"), maxp = tb_ttf_table(&f, base, \"maxp\"), hhea = tb_ttf_table(&f, base, \"hhea\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4417; }
    { const char * tb_v4418 = "    f.glyf = tb_ttf_table(&f, base, \"glyf\"); f.loca = tb_ttf_table(&f, base, \"loca\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4418; }
    { const char * tb_v4419 = "    f.hmtx = tb_ttf_table(&f, base, \"hmtx\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4419; }
    { const char * tb_v4420 = "    uint32_t cmap = tb_ttf_table(&f, base, \"cmap\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4420; }
    { const char * tb_v4421 = "    if (!f.glyf || !f.loca) { free(d); tb_err = \"этот шрифт не TrueType (контуры CFF/OTF пока не читаю): возьми .ttf\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4421; }
    { const char * tb_v4422 = "    if (!head || !maxp || !hhea || !f.hmtx || !cmap) { free(d); tb_err = \"шрифт сломан: нет нужных таблиц\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4422; }
    { const char * tb_v4423 = "    f.upem = (int)tb_u16(&f, head + 18); f.locfmt = tb_s16(&f, head + 50);\n"; *(const char * *)tb_grow(v_lines) = tb_v4423; }
    { const char * tb_v4424 = "    f.nglyphs = (int)tb_u16(&f, maxp + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v4424; }
    { const char * tb_v4425 = "    f.asc = tb_s16(&f, hhea + 4); f.desc = tb_s16(&f, hhea + 6); f.nhm = (int)tb_u16(&f, hhea + 34);\n"; *(const char * *)tb_grow(v_lines) = tb_v4425; }
    { const char * tb_v4426 = "    if (f.upem <= 0 || f.nhm <= 0 || f.asc - f.desc <= 0) { free(d); tb_err = \"шрифт сломан: размеры\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4426; }
    { const char * tb_v4427 = "    // буквы → номера глифов: Unicode-таблица формата 12 (все буквы) или 4 (до U+FFFF)\n"; *(const char * *)tb_grow(v_lines) = tb_v4427; }
    { const char * tb_v4428 = "    unsigned nt = tb_u16(&f, cmap + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v4428; }
    { const char * tb_v4429 = "    int best = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4429; }
    { const char * tb_v4430 = "    for (unsigned i = 0; i < nt; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4430; }
    { const char * tb_v4431 = "        size_t e = cmap + 4 + 8 * (size_t)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v4431; }
    { const char * tb_v4432 = "        unsigned pid = tb_u16(&f, e), eid = tb_u16(&f, e + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v4432; }
    { const char * tb_v4433 = "        uint32_t off = cmap + tb_u32(&f, e + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v4433; }
    { const char * tb_v4434 = "        unsigned fmt = tb_u16(&f, off);\n"; *(const char * *)tb_grow(v_lines) = tb_v4434; }
    { const char * tb_v4435 = "        int score = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4435; }
    { const char * tb_v4436 = "        if (fmt == 12 && (pid == 0 || (pid == 3 && eid == 10))) score = 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v4436; }
    { const char * tb_v4437 = "        else if (fmt == 4 && (pid == 0 || (pid == 3 && eid == 1))) score = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v4437; }
    { const char * tb_v4438 = "        if (score > best) { best = score; f.cmap = off; f.cfmt = (int)fmt; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4438; }
    { const char * tb_v4439 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4439; }
    { const char * tb_v4440 = "    if (!best) { free(d); tb_err = \"в шрифте нет таблицы букв Unicode\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4440; }
    { const char * tb_v4441 = "    tb_font_t *all = realloc(tb_fonts, (size_t)(tb_nfonts + 1) * sizeof(tb_font_t));\n"; *(const char * *)tb_grow(v_lines) = tb_v4441; }
    { const char * tb_v4442 = "    if (!all) { free(d); tb_err = \"не хватило памяти\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4442; }
    { const char * tb_v4443 = "    tb_fonts = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v4443; }
    { const char * tb_v4444 = "    tb_fonts[tb_nfonts++] = f;\n"; *(const char * *)tb_grow(v_lines) = tb_v4444; }
    { const char * tb_v4445 = "    tb_gpu_blend_probe();\n"; *(const char * *)tb_grow(v_lines) = tb_v4445; }
    { const char * tb_v4446 = "    return tb_nfonts - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4446; }
    { const char * tb_v4447 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4447; }
    { const char * tb_v4448 = "static unsigned tb_ttf_glyph(const tb_font_t *f, unsigned u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4448; }
    { const char * tb_v4449 = "    size_t c = f->cmap;\n"; *(const char * *)tb_grow(v_lines) = tb_v4449; }
    { const char * tb_v4450 = "    if (f->cfmt == 12) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4450; }
    { const char * tb_v4451 = "        uint32_t n = tb_u32(f, c + 12);\n"; *(const char * *)tb_grow(v_lines) = tb_v4451; }
    { const char * tb_v4452 = "        for (uint32_t lo = 0, hi = n; lo < hi;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4452; }
    { const char * tb_v4453 = "            uint32_t mid = (lo + hi) / 2; size_t g = c + 16 + 12 * (size_t)mid;\n"; *(const char * *)tb_grow(v_lines) = tb_v4453; }
    { const char * tb_v4454 = "            uint32_t a = tb_u32(f, g), b = tb_u32(f, g + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v4454; }
    { const char * tb_v4455 = "            if (u < a) hi = mid; else if (u > b) lo = mid + 1; else return tb_u32(f, g + 8) + (u - a);\n"; *(const char * *)tb_grow(v_lines) = tb_v4455; }
    { const char * tb_v4456 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v4456; }
    { const char * tb_v4457 = "        return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4457; }
    { const char * tb_v4458 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4458; }
