    { const char * tb_v6598 = "    for (int s = 0; s < TB_GSLOTS; s++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6598; }
    { const char * tb_v6599 = "        if (tb_mtl.cbs[s]) { TB_MSG(void, tb_mtl.cbs[s], \"waitUntilCompleted\"); TB_MSG(void, tb_mtl.cbs[s], \"release\"); tb_mtl.cbs[s] = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6599; }
