    { const char * tb_v7189 = "    struct { uint32_t sType; const void *pNext; VkFlags flags; Display *dpy; Window window; } ci = { 1000004000, 0, 0, tb_dpy, tb_xw };\n"; *(const char * *)tb_grow(v_lines) = tb_v7189; }
    { const char * tb_v7190 = "    VkResult (TBVK_CALL *mk)(VkInstance, const void *, const void *, VkSurfaceKHR *) =\n"; *(const char * *)tb_grow(v_lines) = tb_v7190; }
    { const char * tb_v7191 = "        (VkResult (TBVK_CALL *)(VkInstance, const void *, const void *, VkSurfaceKHR *))tbvk_gipa(tb_vk.inst, \"vkCreateXlibSurfaceKHR\");\n"; *(const char * *)tb_grow(v_lines) = tb_v7191; }
