    { const char * tb_v7194 = "// window_sharp в X11: масштаб из настройки Xft.dpi (её ставят GNOME и KDE), иначе 1\n"; *(const char * *)tb_grow(v_lines) = tb_v7194; }
    { const char * tb_v7195 = "TB_API double tb_gfx_scale(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7195; }
    { const char * tb_v7196 = "    if (!tb_dpy) tb_dpy = XOpenDisplay(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7196; }
    { const char * tb_v7197 = "    if (!tb_dpy) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7197; }
    { const char * tb_v7198 = "    const char *v = XGetDefault(tb_dpy, \"Xft\", \"dpi\");\n"; *(const char * *)tb_grow(v_lines) = tb_v7198; }
