    { const char * tb_v7200 = "    return dpi > 0 ? dpi / 96.0 : 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7200; }
    { const char * tb_v7201 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7201; }
    { const char * tb_v7202 = "TB_API int tb_gfx_open(const char *title) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7202; }
    { const char * tb_v7203 = "    if (!tb_dpy) tb_dpy = XOpenDisplay(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7203; }
    { const char * tb_v7204 = "    if (!tb_dpy) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7204; }
