    { const char * tb_v7206 = "    tb_xw = XCreateSimpleWindow(tb_dpy, RootWindow(tb_dpy, scr), 0, 0, tb_gw, tb_gh, 0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7206; }
    { const char * tb_v7207 = "    tb_xgc = XCreateGC(tb_dpy, tb_xw, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7207; }
    { const char * tb_v7208 = "    XSelectInput(tb_dpy, tb_xw, ExposureMask | KeyPressMask | KeyReleaseMask | ButtonPressMask | ButtonReleaseMask | PointerMotionMask | StructureNotifyMask);\n"; *(const char * *)tb_grow(v_lines) = tb_v7208; }
    { const char * tb_v7209 = "    tb_x_hints(tb_gw, tb_gh, tb_gw, tb_gh);   // размер окна не меняется, пока программа не спросит window_w()\n"; *(const char * *)tb_grow(v_lines) = tb_v7209; }
    { const char * tb_v7210 = "    Xutf8SetWMProperties(tb_dpy, tb_xw, title, title, 0, 0, 0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7210; }
