    { const char * tb_v7212 = "    XSetWMProtocols(tb_dpy, tb_xw, &tb_wm_del, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7212; }
    { const char * tb_v7213 = "    XkbSetDetectableAutoRepeat(tb_dpy, True, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7213; }
    { const char * tb_v7214 = "    XMapWindow(tb_dpy, tb_xw);\n"; *(const char * *)tb_grow(v_lines) = tb_v7214; }
    { const char * tb_v7215 = "    tb_ximg = XCreateImage(tb_dpy, DefaultVisual(tb_dpy, scr), 24, ZPixmap, 0, (char *)tb_px, tb_gw, tb_gh, 32, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7215; }
    { const char * tb_v7216 = "    if (tb_gpu_want()) tb_gpu_on = tb_vk_init(\"VK_KHR_xlib_surface\", tb_x_surface);\n"; *(const char * *)tb_grow(v_lines) = tb_v7216; }
    { const char * tb_v7217 = "    if (!tb_gpu_on) tb_gpu_say(\"процессор\");\n"; *(const char * *)tb_grow(v_lines) = tb_v7217; }
