    { const char * tb_v7220 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7220; }
    { const char * tb_v7221 = "// знак клавиши → буква Unicode (русская раскладка в X11 — свои старые номера 0x6c0..0x6ff)\n"; *(const char * *)tb_grow(v_lines) = tb_v7221; }
    { const char * tb_v7222 = "TB_API unsigned tb_x_uni(KeySym s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7222; }
    { const char * tb_v7223 = "    static const unsigned short cyr[64] = { 0x44e, 0x430, 0x431, 0x446, 0x434, 0x435, 0x444, 0x433, 0x445, 0x438, 0x439, 0x43a, 0x43b, 0x43c, 0x43d, 0x43e, 0x43f, 0x44f, 0x440, 0x441, 0x442, 0x443, 0x436, 0x432, 0x44c, 0x44b, 0x437, 0x448, 0x44d, 0x449, 0x447, 0x44a, 0x42e, 0x410, 0x411, 0x426, 0x414, 0x415, 0x424, 0x413, 0x425, 0x418, 0x419, 0x41a, 0x41b, 0x41c, 0x41d, 0x41e, 0x41f, 0x42f, 0x420, 0x421, 0x422, 0x423, 0x416, 0x412, 0x42c, 0x42b, 0x417, 0x428, 0x42d, 0x429, 0x427, 0x42a };\n"; *(const char * *)tb_grow(v_lines) = tb_v7223; }
    { const char * tb_v7224 = "    if ((s >= 0x20 && s <= 0x7e) || (s >= 0xa0 && s <= 0xff)) return (unsigned)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v7224; }
    { const char * tb_v7225 = "    if ((s & 0xff000000) == 0x01000000) return (unsigned)(s & 0xffffff);\n"; *(const char * *)tb_grow(v_lines) = tb_v7225; }
    { const char * tb_v7226 = "    if (s >= 0x6c0 && s <= 0x6ff) return cyr[s - 0x6c0];\n"; *(const char * *)tb_grow(v_lines) = tb_v7226; }
    { const char * tb_v7227 = "    if (s == 0x6a3) return 0x451;\n"; *(const char * *)tb_grow(v_lines) = tb_v7227; }
    { const char * tb_v7228 = "    if (s == 0x6b3) return 0x401;\n"; *(const char * *)tb_grow(v_lines) = tb_v7228; }
    { const char * tb_v7229 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7229; }
    { const char * tb_v7230 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7230; }
    { const char * tb_v7231 = "TB_API int tb_x_key(KeySym s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7231; }
    { const char * tb_v7232 = "    if (s >= XK_a && s <= XK_z) return 'A' + (int)(s - XK_a);\n"; *(const char * *)tb_grow(v_lines) = tb_v7232; }
    { const char * tb_v7233 = "    if (s >= XK_A && s <= XK_Z) return 'A' + (int)(s - XK_A);\n"; *(const char * *)tb_grow(v_lines) = tb_v7233; }
    { const char * tb_v7234 = "    if (s >= XK_0 && s <= XK_9) return '0' + (int)(s - XK_0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7234; }
    { const char * tb_v7235 = "    switch (s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7235; }
    { const char * tb_v7236 = "    case XK_Return: return TB_K_ENTER; case XK_Escape: return TB_K_ESC; case XK_space: return TB_K_SPACE;\n"; *(const char * *)tb_grow(v_lines) = tb_v7236; }
    { const char * tb_v7237 = "    case XK_BackSpace: return TB_K_BACK; case XK_Tab: return TB_K_TAB; case XK_Up: return TB_K_UP;\n"; *(const char * *)tb_grow(v_lines) = tb_v7237; }
    { const char * tb_v7238 = "    case XK_Down: return TB_K_DOWN; case XK_Left: return TB_K_LEFT; case XK_Right: return TB_K_RIGHT;\n"; *(const char * *)tb_grow(v_lines) = tb_v7238; }
    { const char * tb_v7239 = "    case XK_Shift_L: case XK_Shift_R: return TB_K_SHIFT;\n"; *(const char * *)tb_grow(v_lines) = tb_v7239; }
    { const char * tb_v7240 = "    case XK_Control_L: case XK_Control_R: return TB_K_CTRL;\n"; *(const char * *)tb_grow(v_lines) = tb_v7240; }
    { const char * tb_v7241 = "    case XK_Alt_L: case XK_Alt_R: return TB_K_ALT;\n"; *(const char * *)tb_grow(v_lines) = tb_v7241; }
    { const char * tb_v7242 = "    case XK_Delete: return TB_K_DEL; case XK_Home: return TB_K_HOME; case XK_End: return TB_K_END;\n"; *(const char * *)tb_grow(v_lines) = tb_v7242; }
    { const char * tb_v7243 = "    case XK_Prior: return TB_K_PGUP; case XK_Next: return TB_K_PGDN;\n"; *(const char * *)tb_grow(v_lines) = tb_v7243; }
    { const char * tb_v7244 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7244; }
    { const char * tb_v7245 = "    if (s >= XK_F1 && s <= XK_F12) return TB_K_F1 + (int)(s - XK_F1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7245; }
    { const char * tb_v7246 = "    if (s > 0x20 && s < 0x7f) return (int)s;   // знаки [ ] . , / - = : у X11 номер знака — это его код\n"; *(const char * *)tb_grow(v_lines) = tb_v7246; }
    { const char * tb_v7247 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7247; }
    { const char * tb_v7248 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7248; }
    { const char * tb_v7249 = "// буфер обмена X11: текст держит сама программа-владелец и отдаёт его по просьбе (SelectionRequest)\n"; *(const char * *)tb_grow(v_lines) = tb_v7249; }
    { const char * tb_v7250 = "TB_API char *tb_x_clip = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7250; }
    { const char * tb_v7251 = "TB_API void tb_x_clip_answer(XSelectionRequestEvent *r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7251; }
    { const char * tb_v7252 = "    Atom utf8 = XInternAtom(tb_dpy, \"UTF8_STRING\", False), targets = XInternAtom(tb_dpy, \"TARGETS\", False);\n"; *(const char * *)tb_grow(v_lines) = tb_v7252; }
    { const char * tb_v7253 = "    XSelectionEvent ev;\n"; *(const char * *)tb_grow(v_lines) = tb_v7253; }
    { const char * tb_v7254 = "    memset(&ev, 0, sizeof ev);\n"; *(const char * *)tb_grow(v_lines) = tb_v7254; }
    { const char * tb_v7255 = "    ev.type = SelectionNotify; ev.display = r->display; ev.requestor = r->requestor;\n"; *(const char * *)tb_grow(v_lines) = tb_v7255; }
    { const char * tb_v7256 = "    ev.selection = r->selection; ev.target = r->target; ev.time = r->time; ev.property = None;\n"; *(const char * *)tb_grow(v_lines) = tb_v7256; }
    { const char * tb_v7257 = "    Atom prop = r->property ? r->property : r->target;\n"; *(const char * *)tb_grow(v_lines) = tb_v7257; }
    { const char * tb_v7258 = "    if (r->target == targets) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7258; }
    { const char * tb_v7259 = "        Atom list[3] = { targets, utf8, XA_STRING };\n"; *(const char * *)tb_grow(v_lines) = tb_v7259; }
    { const char * tb_v7260 = "        XChangeProperty(tb_dpy, r->requestor, prop, XA_ATOM, 32, PropModeReplace, (unsigned char *)list, 3);\n"; *(const char * *)tb_grow(v_lines) = tb_v7260; }
    { const char * tb_v7261 = "        ev.property = prop;\n"; *(const char * *)tb_grow(v_lines) = tb_v7261; }
    { const char * tb_v7262 = "    } else if ((r->target == utf8 || r->target == XA_STRING) && tb_x_clip) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7262; }
    { const char * tb_v7263 = "        XChangeProperty(tb_dpy, r->requestor, prop, r->target, 8, PropModeReplace, (unsigned char *)tb_x_clip, (int)strlen(tb_x_clip));\n"; *(const char * *)tb_grow(v_lines) = tb_v7263; }
    { const char * tb_v7264 = "        ev.property = prop;\n"; *(const char * *)tb_grow(v_lines) = tb_v7264; }
    { const char * tb_v7265 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7265; }
    { const char * tb_v7266 = "    XSendEvent(tb_dpy, r->requestor, False, 0, (XEvent *)&ev);\n"; *(const char * *)tb_grow(v_lines) = tb_v7266; }
    { const char * tb_v7267 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7267; }
    { const char * tb_v7268 = "TB_API void tb_gfx_clip_set(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7268; }
    { const char * tb_v7269 = "    free(tb_x_clip);\n"; *(const char * *)tb_grow(v_lines) = tb_v7269; }
    { const char * tb_v7270 = "    tb_x_clip = strdup(s);\n"; *(const char * *)tb_grow(v_lines) = tb_v7270; }
    { const char * tb_v7271 = "    if (!tb_dpy) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7271; }
    { const char * tb_v7272 = "    XSetSelectionOwner(tb_dpy, XInternAtom(tb_dpy, \"CLIPBOARD\", False), tb_xw, CurrentTime);\n"; *(const char * *)tb_grow(v_lines) = tb_v7272; }
    { const char * tb_v7273 = "    XFlush(tb_dpy);\n"; *(const char * *)tb_grow(v_lines) = tb_v7273; }
    { const char * tb_v7274 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7274; }
    { const char * tb_v7275 = "TB_API char *tb_gfx_clip_get(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7275; }
    { const char * tb_v7276 = "    if (!tb_dpy) return tb_x_clip ? strdup(tb_x_clip) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7276; }
    { const char * tb_v7277 = "    Atom clip = XInternAtom(tb_dpy, \"CLIPBOARD\", False), utf8 = XInternAtom(tb_dpy, \"UTF8_STRING\", False);\n"; *(const char * *)tb_grow(v_lines) = tb_v7277; }
    { const char * tb_v7278 = "    Window owner = XGetSelectionOwner(tb_dpy, clip);\n"; *(const char * *)tb_grow(v_lines) = tb_v7278; }
    { const char * tb_v7279 = "    if (owner == tb_xw) return tb_x_clip ? strdup(tb_x_clip) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7279; }
    { const char * tb_v7280 = "    if (owner == None) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7280; }
    { const char * tb_v7281 = "    Atom prop = XInternAtom(tb_dpy, \"TACHBIT_CLIP\", False);\n"; *(const char * *)tb_grow(v_lines) = tb_v7281; }
    { const char * tb_v7282 = "    XConvertSelection(tb_dpy, clip, utf8, prop, tb_xw, CurrentTime);\n"; *(const char * *)tb_grow(v_lines) = tb_v7282; }
    { const char * tb_v7283 = "    XFlush(tb_dpy);\n"; *(const char * *)tb_grow(v_lines) = tb_v7283; }
    { const char * tb_v7284 = "    // ждём ответ владельца не дольше полсекунды; чужие события по дороге не теряем\n"; *(const char * *)tb_grow(v_lines) = tb_v7284; }
    { const char * tb_v7285 = "    long long until = tb_time_ms() + 500;\n"; *(const char * *)tb_grow(v_lines) = tb_v7285; }
    { const char * tb_v7286 = "    while (tb_time_ms() < until) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7286; }
    { const char * tb_v7287 = "        XEvent e;\n"; *(const char * *)tb_grow(v_lines) = tb_v7287; }
    { const char * tb_v7288 = "        if (XCheckTypedWindowEvent(tb_dpy, tb_xw, SelectionNotify, &e)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7288; }
    { const char * tb_v7289 = "            if (e.xselection.property == None) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7289; }
    { const char * tb_v7290 = "            Atom type; int fmt; unsigned long n = 0, rest = 0; unsigned char *data = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7290; }
    { const char * tb_v7291 = "            XGetWindowProperty(tb_dpy, tb_xw, prop, 0, 1 << 24, True, AnyPropertyType, &type, &fmt, &n, &rest, &data);\n"; *(const char * *)tb_grow(v_lines) = tb_v7291; }
    { const char * tb_v7292 = "            char *out = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7292; }
    { const char * tb_v7293 = "            if (data && fmt == 8) { out = malloc(n + 1); if (out) { memcpy(out, data, n); out[n] = 0; } }\n"; *(const char * *)tb_grow(v_lines) = tb_v7293; }
    { const char * tb_v7294 = "            if (data) XFree(data);\n"; *(const char * *)tb_grow(v_lines) = tb_v7294; }
    { const char * tb_v7295 = "            return out;\n"; *(const char * *)tb_grow(v_lines) = tb_v7295; }
    { const char * tb_v7296 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7296; }
    { const char * tb_v7297 = "        if (XCheckTypedEvent(tb_dpy, SelectionRequest, &e)) tb_x_clip_answer(&e.xselectionrequest);\n"; *(const char * *)tb_grow(v_lines) = tb_v7297; }
    { const char * tb_v7298 = "        struct timespec ts = { 0, 2000000 };\n"; *(const char * *)tb_grow(v_lines) = tb_v7298; }
    { const char * tb_v7299 = "        nanosleep(&ts, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7299; }
    { const char * tb_v7300 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7300; }
    { const char * tb_v7301 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7301; }
    { const char * tb_v7302 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7302; }
