    { const char * tb_v7443 = "TB_API long long tb_fps_want = -1, tb_fps_v = 0, tb_fps_n = 0, tb_fps_t0 = 0, tb_last_us = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7443; }
