    { const char * tb_v7484 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7484; }
    { const char * tb_v7485 = "    if (tb_gpu_on) { tb_gin = 0; tb_gpu_rect(0, 0, tb_gw, tb_gh, c); }   // всё прежнее закрашено\n"; *(const char * *)tb_grow(v_lines) = tb_v7485; }
