    { const char * tb_v7487 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7487; }
    { const char * tb_v7488 = "TB_API void tb_draw_pixel(long long x, long long y, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7488; }
    { const char * tb_v7489 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7489; }
    { const char * tb_v7490 = "    if (tb_gpu_on) tb_gpu_rect(x, y, 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7490; }
