    { const char * tb_v7704 = "                unsigned char bits = tb_font[g][row];\n"; *(const char * *)tb_grow(v_lines) = tb_v7704; }
    { const char * tb_v7705 = "                for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v7705; }
    { const char * tb_v7706 = "                    if (bits & (0x80 >> col)) tb_cpu_rect(cx + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7706; }
    { const char * tb_v7707 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v7707; }
