    { const char * tb_v7710 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7710; }
    { const char * tb_v7711 = "// ---------- 3D: сетки и камера ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v7711; }
    { const char * tb_v7712 = "// Сетка — список треугольников в мире (x вправо, y вверх, z вперёд). draw_mesh поворачивает её\n"; *(const char * *)tb_grow(v_lines) = tb_v7712; }
    { const char * tb_v7713 = "// вокруг вертикали, ставит в точку, смотрит камерой (угол обзора 60°), обрезает всё ближе 0.05\n"; *(const char * *)tb_grow(v_lines) = tb_v7713; }
    { const char * tb_v7714 = "// и рисует. Ближнее закрывает дальнее: у каждой точки есть глубина (tb_zb на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v7714; }
    { const char * tb_v7715 = "// буфер глубины на видеокарте). Углы, обрезка и плоскость глубины считаются на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v7715; }
    { const char * tb_v7716 = "// а глубину каждой точки видеокарта и процессор считают одной и той же целой формулой:\n"; *(const char * *)tb_grow(v_lines) = tb_v7716; }
    { const char * tb_v7717 = "// кадры совпадают точка в точку.\n"; *(const char * *)tb_grow(v_lines) = tb_v7717; }
    { const char * tb_v7718 = "// сетка: свои углы без повторов (у куба 8, а не 36) и треугольники как три номера угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v7718; }
    { const char * tb_v7719 = "// Каждый угол поворачивается и проецируется один раз на draw_mesh, а не в каждом своём треугольнике\n"; *(const char * *)tb_grow(v_lines) = tb_v7719; }
    { const char * tb_v7720 = "// vi — те же углы в целых (× 4096, по 4 числа: x, y, z, 0) для 3D на видеокарте; bb — коробка вокруг углов;\n"; *(const char * *)tb_grow(v_lines) = tb_v7720; }
    { const char * tb_v7721 = "// big — есть угол дальше 262 144 от центра сетки (в целые не влезает: только старый путь);\n"; *(const char * *)tb_grow(v_lines) = tb_v7721; }
    { const char * tb_v7722 = "// cull — какие грани не видны (0 — сетка не закрытая, считать все), cullok — cull уже посчитан;\n"; *(const char * *)tb_grow(v_lines) = tb_v7722; }
    { const char * tb_v7723 = "// gv, gt — где углы и треугольники сетки в памяти видеокарты; gused — в какой пачке видеокарта её рисует\n"; *(const char * *)tb_grow(v_lines) = tb_v7723; }
    { const char * tb_v7724 = "typedef struct { double *v; long long nv, capv; uint32_t *t, *c; long long n, cap; long long *hk; long long hcap;\n"; *(const char * *)tb_grow(v_lines) = tb_v7724; }
    { const char * tb_v7725 = "    int32_t *vi; double bb[6]; int big, cull, cullok; long long gv, gt, gused;\n"; *(const char * *)tb_grow(v_lines) = tb_v7725; }
    { const char * tb_v7726 = "    long long nch, *chr; double *chs, bs[4]; int chok; } tb_mesh;   // куски: chr — (первый треугольник, сколько), chs и bs — шары (центр, радиус)\n"; *(const char * *)tb_grow(v_lines) = tb_v7726; }
    { const char * tb_v7727 = "TB_API tb_mesh *tb_meshes = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7727; }
    { const char * tb_v7728 = "TB_API long long tb_nmesh = 0, tb_capmesh = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7728; }
    { const char * tb_v7729 = "TB_API double tb_cam[9] = { 0, 0, -5,  1, 0, 0,  0, 1, 0 };   // где камера, вправо, вверх\n"; *(const char * *)tb_grow(v_lines) = tb_v7729; }
    { const char * tb_v7730 = "TB_API double tb_camf[3] = { 0, 0, 1 };                      // вперёд\n"; *(const char * *)tb_grow(v_lines) = tb_v7730; }
    { const char * tb_v7731 = "TB_API long long tb_mesh_new(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7731; }
    { const char * tb_v7732 = "    if (tb_nmesh == tb_capmesh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7732; }
    { const char * tb_v7733 = "        tb_capmesh = tb_capmesh ? tb_capmesh * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v7733; }
    { const char * tb_v7734 = "        tb_meshes = (tb_mesh *)realloc(tb_meshes, sizeof(tb_mesh) * tb_capmesh);\n"; *(const char * *)tb_grow(v_lines) = tb_v7734; }
    { const char * tb_v7735 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7735; }
    { const char * tb_v7736 = "    memset(&tb_meshes[tb_nmesh], 0, sizeof(tb_mesh));\n"; *(const char * *)tb_grow(v_lines) = tb_v7736; }
    { const char * tb_v7737 = "    tb_meshes[tb_nmesh].gused = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7737; }
    { const char * tb_v7738 = "    return tb_nmesh++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7738; }
    { const char * tb_v7739 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7739; }
    { const char * tb_v7740 = "TB_INL uint64_t tb_vhash(const double *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7740; }
    { const char * tb_v7741 = "    uint64_t h = 1469598103934665603ULL, w[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v7741; }
    { const char * tb_v7742 = "    memcpy(w, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v7742; }
    { const char * tb_v7743 = "    for (int i = 0; i < 3; i++) { h ^= w[i]; h *= 1099511628211ULL; h ^= h >> 29; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7743; }
    { const char * tb_v7744 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v7744; }
    { const char * tb_v7745 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7745; }
    { const char * tb_v7746 = "// номер угла (x, y, z) в сетке: такой же уже есть — тот же номер (таблица с открытой адресацией)\n"; *(const char * *)tb_grow(v_lines) = tb_v7746; }
    { const char * tb_v7747 = "static uint32_t tb_mesh_vertex(tb_mesh *m, double x, double y, double z) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7747; }
    { const char * tb_v7748 = "    double p[3] = { x + 0.0, y + 0.0, z + 0.0 };   // + 0.0: -0 и 0 — один угол\n"; *(const char * *)tb_grow(v_lines) = tb_v7748; }
    { const char * tb_v7749 = "    if (m->nv * 2 >= m->hcap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7749; }
    { const char * tb_v7750 = "        long long nc = m->hcap ? m->hcap * 2 : 64;\n"; *(const char * *)tb_grow(v_lines) = tb_v7750; }
    { const char * tb_v7751 = "        long long *nk = (long long *)malloc(sizeof(long long) * nc);\n"; *(const char * *)tb_grow(v_lines) = tb_v7751; }
    { const char * tb_v7752 = "        for (long long i = 0; i < nc; i++) nk[i] = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7752; }
    { const char * tb_v7753 = "        for (long long v = 0; v < m->nv; v++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7753; }
    { const char * tb_v7754 = "            uint64_t h = tb_vhash(m->v + 3 * v) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7754; }
    { const char * tb_v7755 = "            while (nk[h] >= 0) h = (h + 1) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7755; }
    { const char * tb_v7756 = "            nk[h] = v;\n"; *(const char * *)tb_grow(v_lines) = tb_v7756; }
    { const char * tb_v7757 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7757; }
    { const char * tb_v7758 = "        free(m->hk); m->hk = nk; m->hcap = nc;\n"; *(const char * *)tb_grow(v_lines) = tb_v7758; }
    { const char * tb_v7759 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7759; }
    { const char * tb_v7760 = "    uint64_t h = tb_vhash(p) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7760; }
    { const char * tb_v7761 = "    while (m->hk[h] >= 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7761; }
    { const char * tb_v7762 = "        if (memcmp(m->v + 3 * m->hk[h], p, 24) == 0) return (uint32_t)m->hk[h];\n"; *(const char * *)tb_grow(v_lines) = tb_v7762; }
    { const char * tb_v7763 = "        h = (h + 1) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7763; }
    { const char * tb_v7764 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7764; }
    { const char * tb_v7765 = "    if (m->nv == m->capv) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7765; }
    { const char * tb_v7766 = "        m->capv = m->capv ? m->capv * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v7766; }
    { const char * tb_v7767 = "        m->v = (double *)realloc(m->v, sizeof(double) * 3 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v7767; }
    { const char * tb_v7768 = "        m->vi = (int32_t *)realloc(m->vi, sizeof(int32_t) * 4 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v7768; }
    { const char * tb_v7769 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7769; }
    { const char * tb_v7770 = "    memcpy(m->v + 3 * m->nv, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v7770; }
    { const char * tb_v7771 = "    for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7771; }
    { const char * tb_v7772 = "        if (m->nv == 0 || p[i] < m->bb[i]) m->bb[i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7772; }
    { const char * tb_v7773 = "        if (m->nv == 0 || p[i] > m->bb[3 + i]) m->bb[3 + i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7773; }
    { const char * tb_v7774 = "        if (!(fabs(p[i]) < 262144)) m->big = 1;   // и NaN тоже\n"; *(const char * *)tb_grow(v_lines) = tb_v7774; }
    { const char * tb_v7775 = "        m->vi[4 * m->nv + i] = m->big ? 0 : (int32_t)tb_rnd(p[i] * 4096);\n"; *(const char * *)tb_grow(v_lines) = tb_v7775; }
    { const char * tb_v7776 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7776; }
    { const char * tb_v7777 = "    m->vi[4 * m->nv + 3] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7777; }
    { const char * tb_v7778 = "    m->hk[h] = m->nv;\n"; *(const char * *)tb_grow(v_lines) = tb_v7778; }
    { const char * tb_v7779 = "    return (uint32_t)m->nv++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7779; }
    { const char * tb_v7780 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7780; }
    { const char * tb_v7781 = "TB_API void tb_mesh_add(long long id, double x1, double y1, double z1, double x2, double y2, double z2,\n"; *(const char * *)tb_grow(v_lines) = tb_v7781; }
    { const char * tb_v7782 = "                        double x3, double y3, double z3, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7782; }
    { const char * tb_v7783 = "    if (id < 0 || id >= tb_nmesh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7783; }
    { const char * tb_v7784 = "    tb_mesh *m = &tb_meshes[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v7784; }
    { const char * tb_v7785 = "    // видеокарта ещё не нарисовала эту сетку из текущей пачки: сначала отдать пачку (там старая сетка)\n"; *(const char * *)tb_grow(v_lines) = tb_v7785; }
    { const char * tb_v7786 = "    if (tb_gpu_on && m->gused == tb_gbatch) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7786; }
    { const char * tb_v7787 = "    tb_mesh_gdirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7787; }
    { const char * tb_v7788 = "    m->cullok = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7788; }
    { const char * tb_v7789 = "    m->chok = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7789; }
    { const char * tb_v7790 = "    if (m->n == m->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7790; }
    { const char * tb_v7791 = "        m->cap = m->cap ? m->cap * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v7791; }
    { const char * tb_v7792 = "        m->t = (uint32_t *)realloc(m->t, sizeof(uint32_t) * 3 * m->cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v7792; }
    { const char * tb_v7793 = "        m->c = (uint32_t *)realloc(m->c, sizeof(uint32_t) * m->cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v7793; }
    { const char * tb_v7794 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7794; }
    { const char * tb_v7795 = "    uint32_t *t = m->t + 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7795; }
    { const char * tb_v7796 = "    t[0] = tb_mesh_vertex(m, x1, y1, z1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7796; }
    { const char * tb_v7797 = "    t[1] = tb_mesh_vertex(m, x2, y2, z2);\n"; *(const char * *)tb_grow(v_lines) = tb_v7797; }
    { const char * tb_v7798 = "    t[2] = tb_mesh_vertex(m, x3, y3, z3);\n"; *(const char * *)tb_grow(v_lines) = tb_v7798; }
    { const char * tb_v7799 = "    m->c[m->n++] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v7799; }
    { const char * tb_v7800 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7800; }
    { const char * tb_v7801 = "TB_API void tb_camera(double x, double y, double z, double lx, double ly, double lz) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7801; }
    { const char * tb_v7802 = "    double f[3] = { lx - x, ly - y, lz - z }, l = sqrt(f[0] * f[0] + f[1] * f[1] + f[2] * f[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7802; }
    { const char * tb_v7803 = "    if (l < 1e-12) return;   // смотреть в себя нельзя: камера не меняется\n"; *(const char * *)tb_grow(v_lines) = tb_v7803; }
    { const char * tb_v7804 = "    for (int i = 0; i < 3; i++) f[i] /= l;\n"; *(const char * *)tb_grow(v_lines) = tb_v7804; }
    { const char * tb_v7805 = "    double up[3] = { 0, 1, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v7805; }
    { const char * tb_v7806 = "    if (fabs(f[1]) > 0.9999) { up[1] = 0; up[2] = 1; }   // смотрим прямо вверх или вниз\n"; *(const char * *)tb_grow(v_lines) = tb_v7806; }
    { const char * tb_v7807 = "    double r[3] = { up[1] * f[2] - up[2] * f[1], up[2] * f[0] - up[0] * f[2], up[0] * f[1] - up[1] * f[0] };\n"; *(const char * *)tb_grow(v_lines) = tb_v7807; }
    { const char * tb_v7808 = "    l = sqrt(r[0] * r[0] + r[1] * r[1] + r[2] * r[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7808; }
    { const char * tb_v7809 = "    for (int i = 0; i < 3; i++) r[i] /= l;\n"; *(const char * *)tb_grow(v_lines) = tb_v7809; }
    { const char * tb_v7810 = "    double u[3] = { f[1] * r[2] - f[2] * r[1], f[2] * r[0] - f[0] * r[2], f[0] * r[1] - f[1] * r[0] };\n"; *(const char * *)tb_grow(v_lines) = tb_v7810; }
    { const char * tb_v7811 = "    tb_cam[0] = x; tb_cam[1] = y; tb_cam[2] = z;\n"; *(const char * *)tb_grow(v_lines) = tb_v7811; }
    { const char * tb_v7812 = "    for (int i = 0; i < 3; i++) { tb_cam[3 + i] = r[i]; tb_cam[6 + i] = u[i]; tb_camf[i] = f[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7812; }
    { const char * tb_v7813 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7813; }
    { const char * tb_v7814 = "// плоскость глубины по трём точкам экрана (x, y, D); 0 — треугольник ребром к нам, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v7814; }
    { const char * tb_v7815 = "TB_INL int tb_tri3_plane(const double *sx, const double *sy, const double *dd, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7815; }
    { const char * tb_v7816 = "    double e1x = sx[1] - sx[0], e1y = sy[1] - sy[0], e2x = sx[2] - sx[0], e2y = sy[2] - sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v7816; }
    { const char * tb_v7817 = "    double area = e1x * e2y - e1y * e2x;\n"; *(const char * *)tb_grow(v_lines) = tb_v7817; }
    { const char * tb_v7818 = "    if (fabs(area) < 0.5) return 0;   // смотрит на нас ребром: точек почти нет\n"; *(const char * *)tb_grow(v_lines) = tb_v7818; }
    { const char * tb_v7819 = "    double ia = 1 / area;\n"; *(const char * *)tb_grow(v_lines) = tb_v7819; }
    { const char * tb_v7820 = "    double ax = ((dd[1] - dd[0]) * e2y - (dd[2] - dd[0]) * e1y) * ia;\n"; *(const char * *)tb_grow(v_lines) = tb_v7820; }
    { const char * tb_v7821 = "    double by = ((dd[2] - dd[0]) * e1x - (dd[1] - dd[0]) * e2x) * ia;\n"; *(const char * *)tb_grow(v_lines) = tb_v7821; }
    { const char * tb_v7822 = "    if (ax > 1e9) ax = 1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v7822; }
    { const char * tb_v7823 = "    if (ax < -1e9) ax = -1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v7823; }
    { const char * tb_v7824 = "    if (by > 1e9) by = 1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v7824; }
    { const char * tb_v7825 = "    if (by < -1e9) by = -1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v7825; }
    { const char * tb_v7826 = "    double c0 = dd[0] - ax * sx[0] - by * sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v7826; }
    { const char * tb_v7827 = "    // в целые: точка берётся по центру (2x + 1) / 2, поэтому ax / 2; ещё × 64 для точности\n"; *(const char * *)tb_grow(v_lines) = tb_v7827; }
    { const char * tb_v7828 = "    pl[0] = (uint32_t)tb_rnd(ax * 32); pl[1] = (uint32_t)tb_rnd(by * 32); pl[2] = (uint32_t)tb_rnd(c0 * 64);\n"; *(const char * *)tb_grow(v_lines) = tb_v7828; }
    { const char * tb_v7829 = "    return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7829; }
