    { const char * tb_v7895 = "                qx[n] = p->cx + (q->cx - p->cx) * k; qy[n] = p->cy + (q->cy - p->cy) * k; qz[n] = zn; n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7895; }
    { const char * tb_v7896 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v7896; }
    { const char * tb_v7897 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7897; }
    { const char * tb_v7898 = "        if (n < 3) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v7898; }
