    { const char * tb_v7951 = "    uint64_t *e = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(ne ? ne : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v7951; }
    { const char * tb_v7952 = "    double vol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7952; }
