    { const char * tb_v8212 = "// Микшер: 48 000 кадров в секунду, стерео, числа float, блоки по 10 мс.\n"; *(const char * *)tb_grow(v_lines) = tb_v8212; }
    { const char * tb_v8213 = "// Голос = звук + громкость + высота (+ место в мире для 3D). В 3D: громкость падает с\n"; *(const char * *)tb_grow(v_lines) = tb_v8213; }
    { const char * tb_v8214 = "// расстоянием, сторона (лево/право) слышна по громкости И по задержке между ушами (как у\n"; *(const char * *)tb_grow(v_lines) = tb_v8214; }
    { const char * tb_v8215 = "// настоящей головы), дальнее ухо и звук сзади глуше (тень головы), воздух глушит высокие\n"; *(const char * *)tb_grow(v_lines) = tb_v8215; }
    { const char * tb_v8216 = "// у далёких звуков, а движение даёт эффект Доплера. Громкость и место меняются плавно\n"; *(const char * *)tb_grow(v_lines) = tb_v8216; }
    { const char * tb_v8217 = "// внутри блока — без щелчков. На выходе ограничитель: сколько звуков ни играй, не трещит.\n"; *(const char * *)tb_grow(v_lines) = tb_v8217; }
    { const char * tb_v8218 = "// Куда идёт звук: Mac — AudioQueue, Linux — ALSA, Windows — waveOut (библиотеки грузятся при\n"; *(const char * *)tb_grow(v_lines) = tb_v8218; }
    { const char * tb_v8219 = "// запуске; нет их — тишина, программа работает). TB_SOUND_FILE=путь.wav — в файл (проверки),\n"; *(const char * *)tb_grow(v_lines) = tb_v8219; }
    { const char * tb_v8220 = "// TB_SOUND=0 — никуда (время идёт, звуки «играют» молча).\n"; *(const char * *)tb_grow(v_lines) = tb_v8220; }
    { const char * tb_v8221 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v8221; }
    { const char * tb_v8222 = "#include <dlfcn.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v8222; }
    { const char * tb_v8223 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v8223; }
    { const char * tb_v8224 = "#define TB_SR 48000\n"; *(const char * *)tb_grow(v_lines) = tb_v8224; }
    { const char * tb_v8225 = "#define TB_SBLOCK 480\n"; *(const char * *)tb_grow(v_lines) = tb_v8225; }
    { const char * tb_v8226 = "#define TB_NVOICE 64\n"; *(const char * *)tb_grow(v_lines) = tb_v8226; }
    { const char * tb_v8227 = "typedef struct { float *d; long long n; int ch; double rate; int temp; } tb_snd;\n"; *(const char * *)tb_grow(v_lines) = tb_v8227; }
    { const char * tb_v8228 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v8228; }
    { const char * tb_v8229 = "    int on, gen, snd, loop, is3d, fresh, stop;\n"; *(const char * *)tb_grow(v_lines) = tb_v8229; }
    { const char * tb_v8230 = "    double pos, pitch, vol, x, y, z;\n"; *(const char * *)tb_grow(v_lines) = tb_v8230; }
    { const char * tb_v8231 = "    float gl, gr, lpl, lpr;\n"; *(const char * *)tb_grow(v_lines) = tb_v8231; }
    { const char * tb_v8232 = "    double dl, dr, lastd, dop;\n"; *(const char * *)tb_grow(v_lines) = tb_v8232; }
    { const char * tb_v8233 = "} tb_voice;\n"; *(const char * *)tb_grow(v_lines) = tb_v8233; }
    { const char * tb_v8234 = "static tb_snd *tb_snds;\n"; *(const char * *)tb_grow(v_lines) = tb_v8234; }
    { const char * tb_v8235 = "static int tb_nsnd;\n"; *(const char * *)tb_grow(v_lines) = tb_v8235; }
    { const char * tb_v8236 = "static tb_voice tb_voices[TB_NVOICE];\n"; *(const char * *)tb_grow(v_lines) = tb_v8236; }
    { const char * tb_v8237 = "static pthread_mutex_t tb_slock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v8237; }
    { const char * tb_v8238 = "// слушатель: где он, вектор «вправо», вектор «вперёд» (как у camera)\n"; *(const char * *)tb_grow(v_lines) = tb_v8238; }
    { const char * tb_v8239 = "static double tb_lis[9] = { 0, 0, 0, 1, 0, 0, 0, 0, 1 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8239; }
    { const char * tb_v8240 = "static double tb_master = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8240; }
    { const char * tb_v8241 = "static float tb_mg = 1, tb_lim = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8241; }
    { const char * tb_v8242 = "static int tb_snd_started;\n"; *(const char * *)tb_grow(v_lines) = tb_v8242; }
    { const char * tb_v8243 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v8243; }
    { const char * tb_v8244 = "TB_INL float tb_sget(const tb_snd *s, long long i, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8244; }
    { const char * tb_v8245 = "    if (i < 0 || i >= s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8245; }
    { const char * tb_v8246 = "        if (!loop || s->n == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8246; }
    { const char * tb_v8247 = "        i %= s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8247; }
    { const char * tb_v8248 = "        if (i < 0) i += s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8248; }
    { const char * tb_v8249 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8249; }
    { const char * tb_v8250 = "    return s->d[i * s->ch + (c < s->ch ? c : 0)];\n"; *(const char * *)tb_grow(v_lines) = tb_v8250; }
    { const char * tb_v8251 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8251; }
    { const char * tb_v8252 = "// точка между кадрами звука: кривая Эрмита по 4 соседям (чище, чем прямая между двумя)\n"; *(const char * *)tb_grow(v_lines) = tb_v8252; }
    { const char * tb_v8253 = "TB_INL float tb_sread(const tb_snd *s, double p, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8253; }
    { const char * tb_v8254 = "    double fl = floor(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v8254; }
    { const char * tb_v8255 = "    long long i = (long long)fl;\n"; *(const char * *)tb_grow(v_lines) = tb_v8255; }
    { const char * tb_v8256 = "    float t = (float)(p - fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v8256; }
    { const char * tb_v8257 = "    float a = tb_sget(s, i - 1, c, loop), b = tb_sget(s, i, c, loop), cc = tb_sget(s, i + 1, c, loop), d = tb_sget(s, i + 2, c, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v8257; }
    { const char * tb_v8258 = "    float c1 = 0.5f * (cc - a), c2 = a - 2.5f * b + 2 * cc - 0.5f * d, c3 = 0.5f * (d - a) + 1.5f * (b - cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v8258; }
    { const char * tb_v8259 = "    return ((c3 * t + c2) * t + c1) * t + b;\n"; *(const char * *)tb_grow(v_lines) = tb_v8259; }
    { const char * tb_v8260 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8260; }
    { const char * tb_v8261 = "TB_INL float tb_smono(const tb_snd *s, double p, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8261; }
    { const char * tb_v8262 = "    if (s->ch > 1) return 0.5f * (tb_sread(s, p, 0, loop) + tb_sread(s, p, 1, loop));\n"; *(const char * *)tb_grow(v_lines) = tb_v8262; }
    { const char * tb_v8263 = "    return tb_sread(s, p, 0, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v8263; }
    { const char * tb_v8264 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8264; }
    { const char * tb_v8265 = "// голос кончился: временный звук (play_tone) больше не нужен\n"; *(const char * *)tb_grow(v_lines) = tb_v8265; }
    { const char * tb_v8266 = "static void tb_voice_end(tb_voice *v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8266; }
    { const char * tb_v8267 = "    v->on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8267; }
    { const char * tb_v8268 = "    tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v8268; }
    { const char * tb_v8269 = "    if (s->temp && s->d) { free(s->d); s->d = 0; s->n = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8269; }
    { const char * tb_v8270 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8270; }
    { const char * tb_v8271 = "// куда и как громко слышен 3D-голос: громкость ушей, задержка ушей, фильтры, Доплер\n"; *(const char * *)tb_grow(v_lines) = tb_v8271; }
    { const char * tb_v8272 = "static void tb_voice_3d(tb_voice *v, float *tl, float *tr, double *tdl, double *tdr, float *fl, float *fr) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8272; }
    { const char * tb_v8273 = "    double dx = v->x - tb_lis[0], dy = v->y - tb_lis[1], dz = v->z - tb_lis[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v8273; }
    { const char * tb_v8274 = "    double d = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v8274; }
    { const char * tb_v8275 = "    double side = 0, front = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8275; }
    { const char * tb_v8276 = "    if (d > 1e-9) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8276; }
    { const char * tb_v8277 = "        side = (dx * tb_lis[3] + dy * tb_lis[4] + dz * tb_lis[5]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v8277; }
    { const char * tb_v8278 = "        front = (dx * tb_lis[6] + dy * tb_lis[7] + dz * tb_lis[8]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v8278; }
    { const char * tb_v8279 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8279; }
    { const char * tb_v8280 = "    if (d < 0.25) { side *= d / 0.25; front = 1; }   // звук «в голове» — по центру\n"; *(const char * *)tb_grow(v_lines) = tb_v8280; }
    { const char * tb_v8281 = "    double g = d <= 1 ? 1 : 1 / d;                    // громкость падает с расстоянием\n"; *(const char * *)tb_grow(v_lines) = tb_v8281; }
    { const char * tb_v8282 = "    double a = (side + 1) * 0.7853981633974483;      // стороны с равной мощностью\n"; *(const char * *)tb_grow(v_lines) = tb_v8282; }
    { const char * tb_v8283 = "    *tl = (float)(v->vol * g * cos(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v8283; }
    { const char * tb_v8284 = "    *tr = (float)(v->vol * g * sin(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v8284; }
    { const char * tb_v8285 = "    double itd = 0.00066 * TB_SR * fabs(side);        // до 0,66 мс между ушами\n"; *(const char * *)tb_grow(v_lines) = tb_v8285; }
    { const char * tb_v8286 = "    *tdl = side > 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8286; }
    { const char * tb_v8287 = "    *tdr = side < 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8287; }
    { const char * tb_v8288 = "    double fc = 20000 / (1 + d * 0.03);               // воздух: далёкие звуки глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v8288; }
    { const char * tb_v8289 = "    if (front < 0) fc *= 1 - 0.35 * -front;           // сзади глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v8289; }
    { const char * tb_v8290 = "    double fs = fc * (1 - 0.65 * fabs(side));         // дальнее ухо в тени головы\n"; *(const char * *)tb_grow(v_lines) = tb_v8290; }
    { const char * tb_v8291 = "    double cl = side > 0 ? fs : fc, cr = side < 0 ? fs : fc;\n"; *(const char * *)tb_grow(v_lines) = tb_v8291; }
    { const char * tb_v8292 = "    *fl = (float)(1 - exp(-6.283185307179586 * cl / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v8292; }
    { const char * tb_v8293 = "    *fr = (float)(1 - exp(-6.283185307179586 * cr / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v8293; }
    { const char * tb_v8294 = "    // Доплер: как быстро звук приближается (расстояние за блок 10 мс), звук летит 343 ед/с\n"; *(const char * *)tb_grow(v_lines) = tb_v8294; }
    { const char * tb_v8295 = "    double want = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8295; }
    { const char * tb_v8296 = "    if (!v->fresh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8296; }
    { const char * tb_v8297 = "        double sp = (d - v->lastd) * TB_SR / TB_SBLOCK;\n"; *(const char * *)tb_grow(v_lines) = tb_v8297; }
    { const char * tb_v8298 = "        if (fabs(sp) < 686) want = 343 / (343 + sp);   // быстрее — это прыжок, не движение\n"; *(const char * *)tb_grow(v_lines) = tb_v8298; }
    { const char * tb_v8299 = "        if (want < 0.5) want = 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v8299; }
    { const char * tb_v8300 = "        if (want > 2) want = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v8300; }
    { const char * tb_v8301 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8301; }
    { const char * tb_v8302 = "    v->dop = v->fresh ? 1 : v->dop * 0.8 + want * 0.2;\n"; *(const char * *)tb_grow(v_lines) = tb_v8302; }
    { const char * tb_v8303 = "    v->lastd = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v8303; }
    { const char * tb_v8304 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8304; }
    { const char * tb_v8305 = "// смешать n кадров всех голосов в out (стерео, по очереди лево-право)\n"; *(const char * *)tb_grow(v_lines) = tb_v8305; }
    { const char * tb_v8306 = "static void tb_mix(float *out, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8306; }
    { const char * tb_v8307 = "    memset(out, 0, sizeof(float) * 2 * (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v8307; }
    { const char * tb_v8308 = "    pthread_mutex_lock(&tb_slock);\n"; *(const char * *)tb_grow(v_lines) = tb_v8308; }
    { const char * tb_v8309 = "    for (int k = 0; k < TB_NVOICE; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8309; }
    { const char * tb_v8310 = "        tb_voice *v = &tb_voices[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v8310; }
    { const char * tb_v8311 = "        if (!v->on) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v8311; }
    { const char * tb_v8312 = "        tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v8312; }
    { const char * tb_v8313 = "        if (!s->d || s->n == 0) { tb_voice_end(v); continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8313; }
    { const char * tb_v8314 = "        float tl = (float)v->vol, tr = (float)v->vol, al = 1, ar = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8314; }
    { const char * tb_v8315 = "        double tdl = 0, tdr = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8315; }
    { const char * tb_v8316 = "        if (v->is3d) tb_voice_3d(v, &tl, &tr, &tdl, &tdr, &al, &ar);\n"; *(const char * *)tb_grow(v_lines) = tb_v8316; }
    { const char * tb_v8317 = "        if (v->stop) { tl = 0; tr = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8317; }
    { const char * tb_v8318 = "        if (v->fresh) { v->gl = tl; v->gr = tr; v->dl = tdl; v->dr = tdr; v->fresh = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8318; }
    { const char * tb_v8319 = "        double step = s->rate / TB_SR * v->pitch * (v->is3d ? v->dop : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v8319; }
    { const char * tb_v8320 = "        float gl = v->gl, gr = v->gr, dgl = (tl - gl) / n, dgr = (tr - gr) / n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8320; }
    { const char * tb_v8321 = "        double dl = v->dl, dr = v->dr, ddl = (tdl - dl) / n, ddr = (tdr - dr) / n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8321; }
    { const char * tb_v8322 = "        int done = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8322; }
    { const char * tb_v8323 = "        for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8323; }
    { const char * tb_v8324 = "            float l, r;\n"; *(const char * *)tb_grow(v_lines) = tb_v8324; }
    { const char * tb_v8325 = "            if (v->is3d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8325; }
    { const char * tb_v8326 = "                l = tb_smono(s, v->pos - dl * step, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v8326; }
    { const char * tb_v8327 = "                r = tb_smono(s, v->pos - dr * step, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v8327; }
    { const char * tb_v8328 = "                v->lpl += al * (l - v->lpl);\n"; *(const char * *)tb_grow(v_lines) = tb_v8328; }
    { const char * tb_v8329 = "                v->lpr += ar * (r - v->lpr);\n"; *(const char * *)tb_grow(v_lines) = tb_v8329; }
    { const char * tb_v8330 = "                l = v->lpl;\n"; *(const char * *)tb_grow(v_lines) = tb_v8330; }
    { const char * tb_v8331 = "                r = v->lpr;\n"; *(const char * *)tb_grow(v_lines) = tb_v8331; }
    { const char * tb_v8332 = "            } else if (s->ch > 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8332; }
    { const char * tb_v8333 = "                l = tb_sread(s, v->pos, 0, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v8333; }
    { const char * tb_v8334 = "                r = tb_sread(s, v->pos, 1, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v8334; }
    { const char * tb_v8335 = "            } else {\n"; *(const char * *)tb_grow(v_lines) = tb_v8335; }
    { const char * tb_v8336 = "                l = r = tb_sread(s, v->pos, 0, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v8336; }
    { const char * tb_v8337 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v8337; }
    { const char * tb_v8338 = "            out[2 * i] += l * gl;\n"; *(const char * *)tb_grow(v_lines) = tb_v8338; }
    { const char * tb_v8339 = "            out[2 * i + 1] += r * gr;\n"; *(const char * *)tb_grow(v_lines) = tb_v8339; }
    { const char * tb_v8340 = "            gl += dgl; gr += dgr; dl += ddl; dr += ddr;\n"; *(const char * *)tb_grow(v_lines) = tb_v8340; }
    { const char * tb_v8341 = "            v->pos += step;\n"; *(const char * *)tb_grow(v_lines) = tb_v8341; }
    { const char * tb_v8342 = "            if (v->pos >= (double)s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8342; }
    { const char * tb_v8343 = "                if (v->loop) v->pos -= (double)s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8343; }
    { const char * tb_v8344 = "                else { done = 1; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8344; }
    { const char * tb_v8345 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v8345; }
    { const char * tb_v8346 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8346; }
    { const char * tb_v8347 = "        v->gl = tl; v->gr = tr; v->dl = tdl; v->dr = tdr;\n"; *(const char * *)tb_grow(v_lines) = tb_v8347; }
    { const char * tb_v8348 = "        if (done || v->stop) tb_voice_end(v);\n"; *(const char * *)tb_grow(v_lines) = tb_v8348; }
    { const char * tb_v8349 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8349; }
    { const char * tb_v8350 = "    float mt = (float)tb_master;\n"; *(const char * *)tb_grow(v_lines) = tb_v8350; }
    { const char * tb_v8351 = "    pthread_mutex_unlock(&tb_slock);\n"; *(const char * *)tb_grow(v_lines) = tb_v8351; }
    { const char * tb_v8352 = "    // общая громкость (плавно) и ограничитель: громко — сразу тише, потом медленно назад\n"; *(const char * *)tb_grow(v_lines) = tb_v8352; }
